// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Temel muhasebe ve finansal tablo analizi: bilanço eşitliği, gelir tablosu, cari oran, kârlılık marjları, amortisman ve başabaş noktası (orta).
const ozEconomics18Orta = <(String, String, List<String>, String)>[
  ('Toplam varlıkları 850.000 TL ve toplam yabancı kaynakları 320.000 TL olan bir ticaret işletmesinin özkaynak tutarı kaç TL\'dir?', '530.000 TL', ['1.170.000 TL', '430.000 TL', '320.000 TL'], 'Temel muhasebe eşitliğine göre Özkaynaklar = Varlıklar - Yabancı Kaynaklar olduğundan 850.000 - 320.000 = 530.000 TL bulunur.'),
  ('Dönen varlıkları 240.000 TL, duran varlıkları 460.000 TL ve özkaynakları 410.000 TL olan bir işletmenin toplam borçları (yabancı kaynakları) ne kadardır?', '290.000 TL', ['700.000 TL', '170.000 TL', '650.000 TL'], 'Toplam varlıklar 240.000 + 460.000 = 700.000 TL\'dir; Yabancı Kaynaklar = 700.000 - 410.000 = 290.000 TL olarak hesaplanır.'),
  ('Kısa vadeli borçları 150.000 TL, uzun vadeli borçları 200.000 TL ve özkaynakları 600.000 TL olan bir işletmede duran varlıklar 550.000 TL ise dönen varlıklar kaç TL\'dir?', '400.000 TL', ['950.000 TL', '350.000 TL', '500.000 TL'], 'Toplam pasif (kaynaklar) 150.000 + 200.000 + 600.000 = 950.000 TL olup toplam aktife eşittir; Dönen Varlıklar = 950.000 - 550.000 = 400.000 TL\'dir.'),
  ('Bir mobilya mağazasının satmak amacıyla vitrininde sergilediği koltuk takımları ile kendi muhasebe ofisinde kullandığı çalışma masası bilançoda sırasıyla hangi gruplarda izlenir?', 'Dönen varlıklar - Duran varlıklar', ['Duran varlıklar - Dönen varlıklar', 'Dönen varlıklar - Kısa vadeli yabancı kaynaklar', 'Özkaynaklar - Duran varlıklar'], 'Satış amaçlı koltuk takımları "Ticari Mallar" olarak dönen varlıklarda, ofiste kullanılan masa ise "Demirbaşlar" olarak duran varlıklarda yer alır.'),
  ('Bir otomotiv galerisi için satmak üzere aldığı binek otomobil "Ticari Mallar" hesabında izlenirken, bir tekstil fabrikasının genel müdürüne tahsis ettiği binek otomobil "Taşıtlar" hesabında izlenir. Bu ayrımın temel nedeni nedir?', 'Varlığın edinilme ve işletmede kullanılma amacı', ['Varlığın satın alındığı tarihteki piyasa fiyatı', 'Varlığın peşin mi yoksa vadeli mi satın alındığı', 'Varlığın yerli üretim ya da ithal olması'], 'Bilanço sınıflandırmasında varlığın fiziksel niteliğinden ziyade işletmedeki kullanım niyeti (satışa konu olma veya faaliyetlerde uzun süreli kullanım) belirleyicidir.'),
  ('Tekdüzen Hesap Planı esaslarına göre düzenlenen bir Türkiye bilançosunda aktif ve pasif kalemler hangi ölçüte göre yukarıdan aşağıya sıralanır?', 'Aktifler en çok likitten en az likide, pasifler en kısa vadeliden en uzun vadeliye', ['Aktifler en az likitten en çok likide, pasifler özkaynaklardan kısa vadeli borçlara', 'Aktifler piyasa değerine göre büyükten küçüğe, pasifler faiz oranına göre yüksekten düşüğe', 'Aktifler edinim tarihine göre eskiden yeniye, pasifler alacaklı sayısına göre çoktan aza'], 'Türkiye uygulamasında aktifler likiditesi en yüksek olan hazır değerlerden başlar, pasifler ise vadesi en kısa olan borçlardan başlayıp özkaynaklara doğru sıralanır.'),
  ('İşletmenin geçici fiyat değişimlerinden veya faiz/temettü gelirinden yararlanmak amacıyla kısa vadeli olarak satın aldığı hisse senetleri ve tahviller hangi grupta izlenir?', 'Menkul kıymetler (Dönen varlıklar)', ['Mali duran varlıklar (Duran varlıklar)', 'Ödenmiş sermaye (Özkaynaklar)', 'Mali borçlar (Kısa vadeli yabancı kaynaklar)'], 'Kısa vadeli getiri amacıyla alınan ve istendiğinde nakde çevrilmesi planlanan finansal araçlar dönen varlıklar içindeki menkul kıymetler grubunda raporlanır.'),
  ('Bir şirketin başka bir şirketin yönetimine katılmak ve uzun vadeli stratejik ortaklık kurmak amacıyla satın aldığı hisse senetleri bilançonun hangi bölümünde yer alır?', 'Mali duran varlıklar', ['Menkul kıymetler', 'Hazır değerler', 'Sermaye yedekleri'], 'Uzun vadeli ortaklık ve kontrol gücü amacıyla elde tutulan pay senetleri spekülatif değildir; bu nedenle duran varlıklar içindeki "Mali Duran Varlıklar" grubunda izlenir.'),
  ('Bir işletmenin satıcılardan veresiye (açık hesap) mal satın alması sonucunda doğan borcu bilançoda hangi hesap grubunda takip edilir?', 'Ticari borçlar', ['Mali borçlar', 'Diğer borçlar', 'Alınan avanslar'], 'İşletmenin ana faaliyet konusuyla ilgili mal ve hizmet alımlarından kaynaklanan senetli veya senetsiz yükümlülükler "Ticari Borçlar" grubunda izlenir.'),
  ('İşletmenin kredi kuruluşlarından (bankalardan) çektiği kısa vadeli nakit krediler bilançoda hangi alt grupta raporlanır?', 'Mali borçlar', ['Ticari borçlar', 'Ödenecek vergi ve diğer yükümlülükler', 'Borç ve gider karşılıkları'], 'Banka kredileri ve çıkarılmış finansman bonoları gibi para ve sermaye piyasalarından sağlanan fonlar "Mali Borçlar" grubunda gösterilir.'),
  ('Peşin 90.000 TL ödeyerek ticari mal satın alan bir işletmenin temel muhasebe eşitliğinde nasıl bir değişim meydana gelir?', 'Toplam varlık tutarı değişmez, yalnızca dönen varlıkların kendi içindeki dağılımı değişir', ['Toplam varlıklar 90.000 TL artarken kısa vadeli yabancı kaynaklar da 90.000 TL artar', 'Dönen varlıklar 90.000 TL azalırken işletmenin özkaynakları da 90.000 TL azalır', 'Duran varlıklar 90.000 TL artarken dönen varlıklar 90.000 TL tutarında azalır'], 'Kasadan nakit çıkarken aynı tutarda ticari mal stoğu girdiği için bir dönen varlık azalır, diğer dönen varlık artar; bilanço büyüklüğü sabit kalır.'),
  ('Bir işletme, satıcıya olan 50.000 TL tutarındaki senetsiz borcunu banka hesabından havale yaparak ödediğinde bilançoda hangi etki görülür?', 'Hem dönen varlıklar hem de kısa vadeli yabancı kaynaklar 50.000 TL azalır', ['Dönen varlıklar 50.000 TL azalırken özkaynaklar 50.000 TL artış gösterir', 'Aktif toplamı değişmezken pasif toplamı 50.000 TL tutarında küçülür', 'Kısa vadeli yabancı kaynaklar 50.000 TL artarken hazır değerler 50.000 TL azalır'], 'Bankadaki mevduat (dönen varlık) ve satıcılara olan ticari borç (kısa vadeli yabancı kaynak) eş zamanlı olarak 50.000 TL düşer, bilanço daralır.'),
  ('Ortakların işletmeye nakit olarak 300.000 TL ek sermaye koyması bilançonun aktif ve pasifini nasıl etkiler?', 'Dönen varlıklar 300.000 TL artar, özkaynaklar 300.000 TL artar', ['Duran varlıklar 300.000 TL artar, uzun vadeli borçlar 300.000 TL artar', 'Dönen varlıklar 300.000 TL artar, kısa vadeli borçlar 300.000 TL azalır', 'Aktif toplamı sabit kalırken özkaynaklar 300.000 TL artış gösterir'], 'Nakit girişi kasa/banka hesabını (dönen varlıklar) artırırken, sermaye artışı özkaynakları aynı miktarda büyütür.'),
  ('Bir işletme tamamı kredili (veresiye) olarak yeni bir fabrika binası satın aldığında bilanço eşitliğindeki değişim aşağıdakilerden hangisi olur?', 'Duran varlıklar ve yabancı kaynaklar aynı tutarda artar; özkaynaklar değişmez', ['Duran varlıklar artarken dönen varlıklar aynı tutarda azalır; pasif değişmez', 'Dönen varlıklar ve özkaynaklar aynı tutarda artar; yabancı kaynaklar değişmez', 'Yabancı kaynaklar artarken özkaynaklar aynı tutarda azalır; aktif toplamı sabit kalır'], 'Bina alımı duran varlıkları artırır, bedelin borçlanılması ise yabancı kaynakları artırır; gelir veya gider doğmadığından özkaynak değişmez.'),
  ('Uzun vadeli bir banka kredisinin bilanço tarihi itibarıyla vadesinin dolmasına bir yıldan daha az süre kalan anapara taksitleri bilançoda nereye aktarılır?', 'Kısa vadeli yabancı kaynaklara', ['Özkaynaklar içindeki kâr yedeklerine', 'Dönen varlıklar içindeki hazır değerlere', 'Maddi olmayan duran varlıklara'], 'Vadesi bir yılın altına inen uzun vadeli borç taksitleri, bilançonun likidite ve ödeme gücü görünümünü doğru yansıtmak için kısa vadeli yabancı kaynaklara sınıflandırılır.'),
  ('Dönen varlıklar toplamı ile kısa vadeli yabancı kaynaklar toplamı arasındaki farka finans ve muhasebe literatüründe ne ad verilir?', 'Net işletme sermayesi', ['Özsermaye kârlılığı', 'Brüt satış kârı', 'Maddi duran varlık net değeri'], 'Net işletme (çalışma) sermayesi = Dönen Varlıklar - Kısa Vadeli Yabancı Kaynaklar formülüyle hesaplanır ve kısa vadeli borçları karşılama tamponunu gösterir.'),
  ('Dönen varlıkları 360.000 TL, duran varlıkları 640.000 TL, kısa vadeli borçları 210.000 TL ve uzun vadeli borçları 290.000 TL olan bir firmanın net işletme sermayesi kaç TL\'dir?', '150.000 TL', ['500.000 TL', '350.000 TL', '430.000 TL'], 'Net işletme sermayesi = Dönen Varlıklar (360.000 TL) - Kısa Vadeli Yabancı Kaynaklar (210.000 TL) = 150.000 TL\'dir.'),
  ('Bilançoda "Birikmiş Amortismanlar" hesabı nasıl raporlanır ve aktif toplamını nasıl etkiler?', 'Maddi duran varlıklar grubunda eksi (-) işaretli düzenleyici hesap olarak yer alır ve aktif toplamını azaltır', ['Kısa vadeli yabancı kaynaklar grubunda borç kalemi olarak yer alır ve pasif toplamını artırır', 'Özkaynaklar grubunda kâr yedeği olarak raporlanır ve işletmenin özsermayesini büyütür', 'Dönen varlıklar grubunda nakit benzeri bir fon olarak gösterilir ve likiditeyi artırır'], 'Birikmiş amortismanlar aktif düzenleyici (pasif karakterli) bir hesaptır; duran varlıkların brüt değerinden indirilerek net defter değerine ulaşılmasını sağlar.'),
  ('Bilançonun "Özkaynaklar" ana grubunda yer alan "Dönem Net Zararı" hesabı özkaynak toplamını nasıl etkiler?', 'Özkaynaklar grubunda indirim (eksi) kalemi olarak yer alır ve özkaynak toplamını azaltır', ['Dönen varlıklar grubuna aktarılarak işletmenin aktif toplamını büyütür', 'Kısa vadeli yabancı kaynaklara eklenerek üçüncü kişilere olan borçları artırır', 'Özkaynaklar grubunda sermaye yedeği olarak toplanır ve pasifi artırır'], 'Zarar, işletmenin net varlıklarındaki erimeyi ifade eder; bu yüzden pasifte özkaynakları azaltıcı (-) düzenleyici bir kalem olarak raporlanır.'),
  ('Bir şirketin geçmiş yıllarda elde ettiği kârların ortaklara dağıtılmayarak işletme bünyesinde bırakılan kısımları bilançonun hangi bölümünde izlenir?', 'Özkaynaklar (Kâr yedekleri / Geçmiş yıllar kârları)', ['Dönen varlıklar (Bankalar / Hazır değerler)', 'Uzun vadeli yabancı kaynaklar (Mali borçlar)', 'Duran varlıklar (Mali duran varlıklar)'], 'Dağıtılmayan kârlar oto-finansman kaynağıdır ve pasifte Özkaynaklar grubu altında kâr yedekleri veya geçmiş yıllar kârları olarak raporlanır; nakit olarak kasada durması şart değildir.'),
  ('Bir yazılım firmasının müşterisinden, gelecek ay teslim edeceği proje için peşin olarak tahsil ettiği kapora (avans) bilançoda hangi grupta yer alır?', 'Kısa vadeli yabancı kaynaklar (Alınan Avanslar)', ['Dönen varlıklar (Ticari Alacaklar)', 'Özkaynaklar (Dönem Net Kârı)', 'Duran varlıklar (Maddi Olmayan Duran Varlıklar)'], 'Hizmet henüz sunulmadığı için alınan para kazanılmış gelir değildir; müşteriye karşı hizmeti ifa etme yükümlülüğü doğurduğundan kısa vadeli yabancı kaynaklarda izlenir.'),
  ('İşletmenin elinde bulunan müşteri çekleri ile işletmenin kendi satıcılarına keşide edip verdiği çekler bilançoda sırasıyla hangi ana gruplarda raporlanır?', 'Alınan çekler Dönen Varlıklarda; verilen çekler Kısa Vadeli Yabancı Kaynaklarda', ['Her ikisi de Dönen Varlıklar içindeki Ticari Alacaklar grubunda artı değerle', 'Alınan çekler Özkaynaklarda; verilen çekler Uzun Vadeli Yabancı Kaynaklarda', 'Alınan çekler Duran Varlıklarda; verilen çekler Dönen Varlıklarda'], 'Müşteriden alınan çek işletmenin tahsil edeceği bir değerdir (aktif); satıcıya verilen çek ise işletmenin banka hesabından çıkacak bir ödeme yükümlülüğüdür.'),
  ('İşletmenin devlete ödemekle yükümlü olduğu kurumlar vergisi, katma değer vergisi ve sosyal güvenlik prim kesintileri bilançonun hangi alt grubunda raporlanır?', 'Ödenecek vergi ve diğer yükümlülükler', ['Ticari borçlar', 'Mali borçlar', 'Sermaye yedekleri'], 'Vergi dairesi ve sosyal güvenlik kurumlarına olan yasal yükümlülükler kısa vadeli yabancı kaynaklar içindeki "Ödenecek Vergi ve Diğer Yükümlülükler" grubunda gösterilir.'),
  ('Çalışanların yasalar gereği hak kazandığı ancak işten ayrıldıklarında veya emekli olduklarında kendilerine ödenecek olan kıdem tazminatı yükümlülükleri genellikle hangi grupta izlenir?', 'Uzun vadeli yabancı kaynaklar (Borç ve gider karşılıkları)', ['Dönen varlıklar (Gelecek aylara ait giderler)', 'Özkaynaklar (Kâr yedekleri)', 'Maddi olmayan duran varlıklar (Haklar)'], 'Personelin uzun yıllar çalışması sonucu doğan ve ödenmesi bir yıldan uzun vadeye yayılan kıdem tazminatı karşılıkları ağırlıklı olarak uzun vadeli yabancı kaynaklarda raporlanır.'),
  ('Bilançosunda Hazır Değerler 80.000 TL, Ticari Alacaklar 120.000 TL, Stoklar 150.000 TL ve Maddi Duran Varlıklar (Net) 450.000 TL olan ve başka varlığı bulunmayan bir işletmenin dönen varlıkları toplamı kaç TL\'dir?', '350.000 TL', ['800.000 TL', '200.000 TL', '570.000 TL'], 'Dönen varlıklar; Hazır Değerler (80.000) + Ticari Alacaklar (120.000) + Stoklar (150.000) = 350.000 TL\'dir. Maddi duran varlıklar bu gruba dahil edilmez.'),
  ('Bilançosunda Mali Borçlar (6 ay vadeli) 90.000 TL, Ticari Borçlar (3 ay vadeli) 110.000 TL, Uzun Vadeli Banka Kredileri (4 yıl vadeli) 300.000 TL ve Ödenmiş Sermaye 500.000 TL olan bir şirketin kısa vadeli yabancı kaynakları kaç TL\'dir?', '200.000 TL', ['500.000 TL', '410.000 TL', '1.000.000 TL'], 'Vadesi bir yılın altında olan 6 ay vadeli mali borç (90.000 TL) ile 3 ay vadeli ticari borcun (110.000 TL) toplamı 200.000 TL kısa vadeli yabancı kaynak oluşturur.'),
  ('Bir inşaat veya tersane işletmesinde normal faaliyet döngüsü (bir geminin üretilip teslim edilmesi) 18 ay sürüyorsa, bu gemi üretimi için tutulan stoklar bilançoda nerede sınıflandırılır?', 'Dönen varlıklar', ['Maddi duran varlıklar', 'Mali duran varlıklar', 'Uzun vadeli yabancı kaynaklar'], 'Muhasebe standartlarına göre dönen varlık ölçütü "12 ay VEYA işletmenin normal faaliyet döngüsü (hangisi uzunsa)" olduğundan, 18 aylık üretim döngüsündeki stoklar yine dönen varlık sayılır.'),
  ('Aşağıdaki finansal işlemlerden hangisi bilançonun yalnızca pasif tarafındaki kalemler arasında bir yer değiştirmeye neden olur ve aktif toplamını etkilemez?', 'Kısa vadeli satıcı borcunun, satıcının şirkete ortak edilmesiyle sermayeye dönüştürülmesi', ['İşletme kasasındaki nakit parayla peşin olarak yeni bir bilgisayar satın alınması', 'Vadesi gelen alacak senedinin tahsil edilerek karşılığının banka hesabına yatırılması', 'İşletmenin sahip olduğu eski bir kamyonetin defter değeri üzerinden peşin satılması'], 'Satıcı borcu (kısa vadeli yabancı kaynak) azalırken ödenmiş sermaye (özkaynak) aynı tutarda artar; işlem tamamen pasif kalemler arasında gerçekleşir.'),
  ('Bir işletme, müşterisinden olan 45.000 TL\'lik açık hesap (senetsiz) alacağına karşılık müşteriden 90 gün vadeli bir bono (senet) aldığında bilançoda ne değişir?', 'Dönen varlıklar toplamı değişmez; "Alıcılar" azalırken "Alacak Senetleri" artar', ['Dönen varlıklar 45.000 TL artarken kısa vadeli yabancı kaynaklar 45.000 TL artar', 'Duran varlıklar 45.000 TL artarken dönen varlıklar 45.000 TL azalır', 'Aktif toplamı 45.000 TL artarken özkaynaklar 45.000 TL artış gösterir'], 'Senetsiz ticari alacak senetli ticari alacağa dönüşmüştür; her iki hesap da dönen varlıklar içindeki ticari alacaklar grubunda olduğundan grup ve aktif toplamı değişmez.'),
  ('İşletme sahibinin kendi evinin elektrik faturasını işletmenin kasasından ödemesi durumunda muhasebenin "Kişilik Kavramı" gereği bu tutar nasıl kaydedilmelidir?', 'İşletmenin gideri sayılmaz; ortağın işletmeden çektiği para (Ortaklardan Alacaklar) olarak kaydedilir', ['İşletmenin genel yönetim gideri olarak kaydedilerek dönem kârından düşülür', 'Bilançoda maddi olmayan duran varlık olarak aktifleştirilip amortismana tabi tutulur', 'Kısa vadeli ticari borç olarak satıcılar hesabına alacak kaydedilir'], 'Kişilik kavramı gereği ortağın özel harcaması işletme gideri olamaz; işletme kasasından çıkan para ortağın işletmeye olan borcu (Ortaklardan Alacaklar) olarak izlenir.'),
  ('Bir işletmenin tasfiyesine (kapatılmasına) kesin olarak karar verilmişse ve "İşletmenin Sürekliliği" varsayımı ortadan kalkmışsa bilanço sınıflandırmasında ne değişir?', 'Dönen-duran varlık ayrımı anlamını yitirir ve varlıklar net gerçekleşebilir (tasfiye) değerleriyle raporlanır', ['Tüm kısa vadeli yabancı kaynaklar silinerek doğrudan özkaynaklar grubuna kâr olarak aktarılır', 'Varlıkların tamamı tarihsel alış maliyetinin iki katı değerle bilançonun aktifine yazılır', 'Temel muhasebe eşitliği geçersiz kalır ve yalnızca gelir tablosu düzenlenmeye devam edilir'], 'Süreklilik sona erdiğinde uzun vadeli kullanım amacı kalmaz; tüm varlıklar satılıp borçlar ödeneceği için net nakde dönüşüm (tasfiye) değerleri esas alınır.'),
  ('Bir işletmenin başka bir işletmeyi devralırken, devralınan işletmenin net varlıklarının gerçeğe uygun değerinin üzerinde ödediği fark (marka itibarı, müşteri kitlesi vb. için) bilançoda hangi kalemde aktifleştirilir?', 'Şerefiye (Peştamallık) - Maddi olmayan duran varlıklar', ['Ödenmiş sermaye - Özkaynaklar', 'Hazır değerler - Dönen varlıklar', 'Mali borçlar - Uzun vadeli yabancı kaynaklar'], 'Satın alma işlemiyle bedeli parayla ölçülen bu olumlu fark "Şerefiye" (Goodwill) adıyla maddi olmayan duran varlıklar grubunda raporlanır.'),
  ('Muhasebede "İhtiyatlılık (Temkinlilik) Kavramı" gereğince, tahsili şüpheli hale gelen bir ticari alacak için karşılık ayrıldığında bilançoda nasıl bir değişim olur?', 'Aktifte ticari alacakların net değeri azalır, pasifte dönem kârı (özkaynaklar) azalır', ['Aktifte hazır değerler artar, pasifte kısa vadeli yabancı kaynaklar aynı tutarda artar', 'Aktif toplamı değişmezken pasifte uzun vadeli yabancı kaynaklar artış gösterir', 'Hem dönen varlıklar hem de duran varlıklar aynı tutarda artış gösterir'], 'İhtiyatlılık gereği muhtemel zararlar için karşılık ayrılır; "Şüpheli Ticari Alacaklar Karşılığı" aktifte alacakları netleştirerek azaltırken, karşılık gideri özkaynakları düşürür.'),
  ('Anonim şirketlerin yeni hisse senedi ihraç ederken hisseleri üzerinde yazılı nominal (itibari) değerin üzerinde bir fiyattan satmaları sonucu elde ettikleri olumlu fark bilançoda nerede izlenir?', 'Özkaynaklar (Hisse Senedi İhraç Primleri / Sermaye Yedekleri)', ['Kısa Vadeli Yabancı Kaynaklar (Alınan Sipariş Avansları)', 'Dönen Varlıklar (Menkul Kıymetler Cüzdanı)', 'Uzun Vadeli Yabancı Kaynaklar (Çıkarılmış Tahviller)'], 'Emisyon primi olarak da bilinen hisse senedi ihraç primleri ticari kâr değil, sermaye hareketinden doğan bir fazlalıktır ve özkaynaklarda "Sermaye Yedekleri" altında izlenir.'),
  ('Bilanço tarihi itibarıyla vadesine 8 ay kalmış bir alacak senedinin nominal değeri 105.000 TL, bilanço günündeki peşin (iskonto edilmiş) değeri ise 98.000 TL\'dir. Alacak senetleri reeskontu uygulandığında senet bilançoda net kaç TL ile görünür?', '98.000 TL', ['105.000 TL', '203.000 TL', '7.000 TL'], 'Tasarruf (gerçek/peşin) değeriyle değerleme ilkesi gereği 7.000 TL "Alacak Senetleri Reeskontu (-)" ayrılır ve alacak senedi aktifte net 98.000 TL olarak raporlanır.'),
  ('Peşin tahsil edilen ancak hizmeti gelecek faaliyet yılında (1 yıldan daha sonra) sunulacak olan gelir kalemleri bilançonun hangi ana grubunda sınıflandırılır?', 'Uzun vadeli yabancı kaynaklar (Gelecek Yıllara Ait Gelirler)', ['Duran varlıklar (Gelecek Yıllara Ait Giderler)', 'Özkaynaklar (Dönem Net Kârı)', 'Dönen varlıklar (Gelir Tahakkukları)'], 'Henüz hak edilmemiş ve ifası bir yıldan uzun süre sonra gerçekleşecek peşin tahsilatlar, uzun vadeli yükümlülük niteliğinde olup "Gelecek Yıllara Ait Gelirler"de izlenir.'),
  ('Finansal analizde bir işletmenin dönen varlıklarının kısa vadeli yabancı kaynaklarına bölünmesiyle (Dönen Varlıklar / Kısa Vadeli Yabancı Kaynaklar) elde edilen rasyoya ne ad verilir?', 'Cari oran', ['Kaldıraç oranı', 'Özkaynak çarpanı', 'Stok devir hızı'], 'Cari oran, işletmenin kısa vadeli borçlarını dönen varlıklarıyla kaç kat karşılayabildiğini ölçen en temel likidite oranıdır.'),
  ('Gelir tablosu ile bilanço arasındaki organik bağlantıyı kuran ve gelir tablosunun en alt satırından bilançonun pasifine aktarılan kalem aşağıdakilerden hangisidir?', 'Dönem net kârı veya zararı', ['Brüt satış hasılatı toplamı', 'Satılan ticari malların maliyeti', 'Kısa vadeli banka kredileri'], 'Gelir tablosunda gelir ve giderlerin karşılaştırılmasıyla bulunan "Dönem Net Kârı (veya Zararı)", bilançonun Özkaynaklar grubuna aktarılarak iki tabloyu birbirine bağlar.'),
  ('Brüt satışları 500.000 TL, satıştan iadeleri 30.000 TL ve satış iskontoları 20.000 TL olan bir işletmenin net satışları kaç TL\'dir?', '450.000 TL', ['470.000 TL', '480.000 TL', '550.000 TL'], 'Net satışlar = 500.000 - (30.000 + 20.000) = 450.000 TL olarak hesaplanır.'),
  ('Net satışları 800.000 TL ve satılan malın maliyeti 520.000 TL olan bir ticaret işletmesinin brüt satış kârı marjı (brüt kâr / net satışlar) yüzde kaçtır?', '%35', ['%40', '%52', '%65'], 'Brüt kâr = 800.000 - 520.000 = 280.000 TL; brüt kâr marjı = 280.000 / 800.000 = %35 olur.'),
  ('Birim satış fiyatı 120 TL, birim değişken maliyeti 70 TL ve aylık sabit maliyeti 150.000 TL olan bir atölyenin başabaş noktası üretim miktarı kaç adettir?', '3.000 adet', ['2.500 adet', '1.250 adet', '2.140 adet'], 'Birim katkı payı = 120 - 70 = 50 TL; Başabaş miktarı = 150.000 / 50 = 3.000 adettir.'),
  ('Fiyatların sürekli yükseldiği enflasyonist bir ortamda FIFO (İlk Giren İlk Çıkar) stok değerleme yöntemini kullanan bir işletmenin dönem sonu stok değeri nasıl bir eğilim gösterir?', 'Güncel piyasa fiyatlarına yakın ve yüksek görünür', ['En eski alım fiyatlarıyla çok düşük görünür', 'Ağırlıklı ortalama maliyetten daha düşük kalır', 'Satılan malın maliyetinden her zaman yüksek çıkar'], 'FIFO yönteminde eski ucuz stoklar satılan malın maliyetine giderken, son alınan pahalı stoklar dönem sonu envanterinde kalır.'),
  ('Fiyatların sürekli arttığı bir dönemde FIFO yöntemi yerine ağırlıklı ortalama maliyet yöntemi seçilirse satılan malın maliyeti ve brüt kâr nasıl etkilenir?', 'Satılan malın maliyeti daha yüksek, brüt kâr daha düşük çıkar', ['Satılan malın maliyeti daha düşük, brüt kâr daha yüksek çıkar', 'Hem satılan malın maliyeti hem de brüt kâr aynı anda artar', 'Stok devir hızı değişmediği için brüt kâr tutarı hiç etkilenmez'], 'FIFO\'da en ucuz ilk stoklar maliyete yazılırken ortalamada yeni pahalı alımlar da hesaba katıldığı için SMM yükselir ve brüt kâr düşer.'),
  ('Maliyeti 600.000 TL, hurda (kalıntı) değeri 60.000 TL ve ekonomik ömrü 9 yıl olan bir makine için normal (eşit paylı) amortisman yöntemine göre yıllık amortisman gideri kaç TL\'dir?', '60.000 TL', ['66.667 TL', '54.000 TL', '73.333 TL'], 'Amortismana tabi tutar = 600.000 - 60.000 = 540.000 TL; yıllık gider = 540.000 / 9 = 60.000 TL\'dir.'),
  ('Amortisman giderinin işletmenin gelir tablosu ve nakit akışı üzerindeki doğrudan etkisi açısından hangisi doğrudur?', 'Nakit çıkışı gerektirmeyen bir gider olup vergi matrahını azaltır', ['Her ay kasadan doğrudan nakit çıkışına yol açan sabit ödemedir', 'Yalnızca bilanço aktifini büyütür, gelir tablosunda yer almaz', 'Doğrudan brüt satış hasılatına eklenerek net kârı yükseltir'], 'Amortisman nakit çıkışı gerektirmeyen bir giderdir; dönem kârını ve dolayısıyla ödenecek vergiyi azaltır.'),
  ('Dönem başı mal stoku 90.000 TL, dönem içi net mal alışı 410.000 TL ve dönem sonu mal stoku 140.000 TL olan bir mağazanın satılan ticari mallar maliyeti kaç TL\'dir?', '360.000 TL', ['460.000 TL', '500.000 TL', '320.000 TL'], 'Satılan malın maliyeti = Dönem başı stok + Dönem içi alışlar - Dönem sonu stok = 90.000 + 410.000 - 140.000 = 360.000 TL.'),
  ('Bir işletmede üretim hacmi kapasite sınırları içinde iki katına çıkarıldığında birim başına düşen sabit maliyet ve birim değişken maliyet nasıl değişir?', 'Birim sabit maliyet yarıya iner, birim değişken maliyet sabit kalır', ['Birim sabit maliyet sabit kalır, birim değişken maliyet iki katına çıkar', 'Her iki birim maliyet kalemi de yarı yarıya azalma gösterir', 'Birim sabit maliyet iki katına çıkarken birim değişken maliyet düşer'], 'Toplam sabit maliyet değişmediğinden üretim ikiye katlanınca birim sabit maliyet yarıya düşer; doğrusal yapıda birim değişken maliyet değişmez.'),
  ('Birim satış fiyatı 200 TL ve birim değişken maliyeti 130 TL olan bir üründe katkı oranı (katkı payı yüzdesi) yüzde kaçtır?', '%35', ['%65', '%70', '%54'], 'Birim katkı payı = 200 - 130 = 70 TL; katkı oranı = 70 / 200 = %35 olarak bulunur.'),
  ('Brüt satış kârı 340.000 TL, pazarlama giderleri 85.000 TL, genel yönetim giderleri 95.000 TL ve kredi faiz giderleri 40.000 TL olan bir şirketin esas faaliyet kârı kaç TL\'dir?', '160.000 TL', ['120.000 TL', '200.000 TL', '255.000 TL'], 'Faaliyet kârı hesaplanırken faiz (finansman) gideri düşülmez: 340.000 - (85.000 + 95.000) = 160.000 TL.'),
  ('Sabit maliyetleri çok yüksek, birim değişken maliyetleri ise çok düşük olan bir yazılım veya havayolu şirketinin başabaş noktasını geçtikten sonraki kârlılık davranışı nasıldır?', 'İlave her satışın büyük kısmı doğrudan kâra dönüşür', ['Ek satışların kâra etkisi hammadde yoğun sektörden düşüktür', 'Birim katkı payı düşük olduğu için kâr çok yavaş artar', 'Başabaş sonrasında toplam maliyetler gelirlerden hızlı büyür'], 'Birim değişken maliyet düşükse birim katkı payı çok yüksektir; sabit giderler karşılandıktan sonra her ek satış yüksek kâr yaratır.'),
  ('Depoya önce tanesi 40 TL\'den 100 adet, sonra tanesi 60 TL\'den 100 adet ürün alan bir işletme, ağırlıklı ortalama maliyet yöntemine göre 150 adet ürün sattığında satılan malın maliyeti kaç TL olur?', '7.500 TL', ['7.000 TL', '8.000 TL', '6.000 TL'], 'Toplam maliyet = 4.000 + 6.000 = 10.000 TL; birim ortalama = 10.000 / 200 = 50 TL; 150 adet SMM = 150 x 50 = 7.500 TL.'),
  ('Depoya önce tanesi 30 TL\'den 200 adet, ardından tanesi 50 TL\'den 150 adet mal alan bir tüccar, FIFO yöntemine göre 240 adet mal sattığında dönem sonu stok değeri kaç TL kalır?', '5.500 TL', ['3.300 TL', '4.400 TL', '6.000 TL'], '240 adedin 200\'ü ilk partiden, 40\'ı ikinci partiden çıkar; geriye 50 TL\'lik partiden 110 adet kalır: 110 x 50 = 5.500 TL.'),
  ('Gelir tablosunda yer alan "finansman giderleri" kalemi esas olarak işletmenin hangi tür işlemlerinden kaynaklanır?', 'Kullanılan yabancı kaynakların faiz ve kur farkı maliyetlerinden', ['Üretim hattındaki makinelerin yıllık bakım ve onarım işlerinden', 'Pazarlama ekibine ödenen satış primi ve seyahat harcamalarından', 'Müşterilere erken ödeme karşılığında tanınan kasa iskontolarından'], 'Banka kredisi faizleri, tahvil faizleri ve borçlanma kaynaklı kur farkları finansman giderlerini oluşturur.'),
  ('Birim satış fiyatı ve sabit maliyetleri değişmeyen bir fabrikada, enerji zamları nedeniyle birim değişken maliyet artarsa başabaş noktası nasıl etkilenir?', 'Birim katkı payı azaldığı için başabaş üretim miktarı yükselir', ['Birim katkı payı arttığı için başabaş üretim miktarı düşer', 'Sabit maliyet değişmediğinden başabaş miktarı sabit kalır', 'Toplam gelir eğrisinin eğimi dikleşerek başabaşı erkene çeker'], 'Değişken maliyet artışı birim katkı payını küçültür; aynı sabit maliyeti karşılamak için daha fazla adet satılması gerekir.'),
  ('Aylık sabit giderleri 96.000 TL ve katkı oranı %40 olan bir kafenin başabaş noktası satış tutarı (cirosu) kaç TL\'dir?', '240.000 TL', ['160.000 TL', '384.000 TL', '134.400 TL'], 'Başabaş satış tutarı = Sabit maliyet / Katkı oranı = 96.000 / 0,40 = 240.000 TL.'),
  ('Bir üretim işletmesinde fabrika binasının amortismanı ile yönetim binasının amortismanı gelir tablosunda hangi kalemler altında sınıflandırılır?', 'Fabrika amortismanı üretim maliyetinde, yönetiminki genel yönetim giderinde', ['Her ikisi de doğrudan faaliyet dışı olağandışı giderler kaleminde', 'Fabrika amortismanı pazarlama giderinde, yönetiminki finansmanda', 'Her ikisi de brüt satışlardan indirilen satış indirimleri grubunda'], 'Üretimle ilgili amortisman genel üretim gideri olarak ürün maliyetine (SMM) girer; yönetim binası amortismanı ise faaliyet gideridir.'),
  ('Faaliyet kârı 250.000 TL, faiz geliri 30.000 TL, finansman gideri 80.000 TL ve vergi oranı %25 olan bir şirketin dönem net kârı kaç TL\'dir?', '150.000 TL', ['200.000 TL', '187.500 TL', '165.000 TL'], 'Vergi öncesi kâr = 250.000 + 30.000 - 80.000 = 200.000 TL; Vergi = 50.000 TL; Net kâr = 150.000 TL.'),
  ('Elektrik faturasının hem sabit bir abonelik bedeli hem de tüketilen kilovatsaat başına artan bir bedel içermesi maliyet muhasebesinde nasıl adlandırılır?', 'Karma (yarı değişken) maliyet', ['Tamamen batık maliyet', 'Fırsat (alternatif) maliyeti', 'Doğrudan işçilik maliyeti'], 'Hem sabit bir taban ücreti hem de faaliyet hacmine bağlı değişken bileşen barındıran giderlere karma maliyet denir.'),
  ('Bir işletmenin brüt satış kârı pozitif ve yüksek iken esas faaliyet kârının negatif (zarar) çıkması en çok hangi durumu işaret eder?', 'Pazarlama, yönetim ve Ar-Ge giderlerinin aşırı yüksek olduğunu', ['Hammadde alış fiyatlarının satış fiyatının üzerinde kaldığını', 'Kredi faizlerinin ve kurumlar vergisi yükünün çok ağır olduğunu', 'Müşterilerden gelen satış iadelerinin tüm hasılatı erittiğini'], 'Brüt kâr ile faaliyet kârı arasındaki fark faaliyet giderleridir (Ar-Ge, pazarlama, genel yönetim); bunların yüksekliği faaliyet zararına yol açar.'),
  ('Sabit maliyeti 180.000 TL, birim satış fiyatı 90 TL ve birim değişken maliyeti 54 TL olan bir işletmenin 72.000 TL vergi öncesi kâr hedefini yakalaması için kaç birim ürün satması gerekir?', '7.000 birim', ['5.000 birim', '6.200 birim', '4.667 birim'], 'Birim katkı payı = 90 - 54 = 36 TL; Hedef satış miktarı = (180.000 + 72.000) / 36 = 252.000 / 36 = 7.000 birim.'),
  ('Dönem sonu mal stoku fiziki sayım hatası yüzünden gerçekte olduğundan 50.000 TL daha fazla yazılırsa cari dönemin gelir tablosu bundan nasıl etkilenir?', 'Satılan malın maliyeti düşük, brüt kâr 50.000 TL yüksek görünür', ['Satılan malın maliyeti yüksek, brüt kâr 50.000 TL düşük görünür', 'Brüt satışlar kalemi 50.000 TL azalır fakat net kâr hiç değişmez', 'Yalnızca genel yönetim giderleri artar, brüt kâr sabit kalır'], 'SMM = Dönem başı + Alışlar - Dönem sonu stok olduğundan, dönem sonu stok fazla yazılırsa SMM düşer ve kâr şişkin görünür.'),
  ('Net satışları 600.000 TL, brüt kâr marjı %40 ve faaliyet giderleri 150.000 TL olan bir işletmenin esas faaliyet kârı kaç TL\'dir?', '90.000 TL', ['240.000 TL', '210.000 TL', '110.000 TL'], 'Brüt kâr = 600.000 x 0,40 = 240.000 TL; Esas faaliyet kârı = 240.000 - 150.000 = 90.000 TL.'),
  ('Başabaş analizinde kullanılan doğrusal maliyet-hacim-kâr grafiklerinde toplam gelir doğrusunun başlangıç noktası neresidir?', 'Orijin noktası', ['Yatay eksendeki başabaş üretim miktarı', 'Dikey eksendeki toplam sabit maliyet düzeyi', 'Toplam değişken maliyetin tepe noktası'], 'Hiç satış yapılmadığında (miktar = 0) toplam gelir de sıfır olacağı için toplam gelir doğrusu orijinden (0,0) başlar.'),
  ('Başabaş grafiğinde toplam maliyet doğrusu dikey (tutar) eksenini hangi noktada keser ve eğimi neyi ifade eder?', 'Toplam sabit maliyette keser, eğimi birim değişken maliyeti verir', ['Sıfır noktasında keser, eğimi birim satış fiyatını gösterir', 'Başabaş cirosunda keser, eğimi birim katkı payını yansıtır', 'Brüt kâr tutarında keser, eğimi ortalama sabit maliyeti verir'], 'Üretim sıfırken toplam maliyet sabit maliyete eşittir (kesim noktası); her ek birimde maliyet birim değişken maliyet kadar artar (eğim).'),
  ('Bir atölyede aylık sabit maliyet 84.000 TL, birim değişken maliyet 45 TL ve hedeflenen başabaş üretim miktarı 2.400 adet ise ürünün birim satış fiyatı kaç TL olmalıdır?', '80 TL', ['75 TL', '85 TL', '90 TL'], 'Gerekli birim katkı payı = 84.000 / 2.400 = 35 TL; Birim satış fiyatı = 45 + 35 = 80 TL olmalıdır.'),
  ('1 Mart\'ta tanesi 100 TL\'den 50 adet, 10 Mart\'ta tanesi 130 TL\'den 50 adet kulaklık alan bir mağaza, 15 Mart\'ta 70 adet kulaklığı tanesi 200 TL\'den satmıştır. FIFO yöntemine göre brüt satış kârı kaç TL\'dir?', '6.400 TL', ['5.900 TL', '6.150 TL', '7.000 TL'], 'Hasılat = 70 x 200 = 14.000 TL. FIFO ile SMM = (50 x 100) + (20 x 130) = 5.000 + 2.600 = 7.600 TL. Brüt kâr = 14.000 - 7.600 = 6.400 TL.'),
  ('Bir üretim tesisinde belirli bir kapasite aralığında sabit kalan ancak üretim 10.000 adedi aştığında ikinci vardiya şefi alınmasıyla sıçrama yapan maliyetlere ne ad verilir?', 'Basamaklı (kademeli) sabit maliyet', ['Doğrusal değişken hammadde maliyeti', 'Birim başına azalan marjinal maliyet', 'Faaliyet dışı olağandışı maliyet'], 'Belirli faaliyet aralıklarında sabit kalıp kapasite eşikleri aşıldığında kademeli olarak artan giderlere basamaklı sabit maliyet denir.'),
  ('Maliyeti 320.000 TL, hurda değeri sıfır ve ekonomik ömrü 8 yıl olan bir fırının 5. yıl sonundaki birikmiş amortisman tutarı ve net defter değeri (normal yönteme göre) sırasıyla kaç TL\'dir?', '200.000 TL ve 120.000 TL', ['160.000 TL ve 160.000 TL', '120.000 TL ve 200.000 TL', '240.000 TL ve 80.000 TL'], 'Yıllık amortisman = 320.000 / 8 = 40.000 TL; 5 yıllık birikmiş = 200.000 TL; Net defter değeri = 320.000 - 200.000 = 120.000 TL.'),
  ('Bir perakende zinciri birim satış fiyatını %10 düşürdüğünde birim değişken maliyeti ve sabit giderleri aynı kalırsa katkı oranı ve başabaş noktası nasıl değişir?', 'Katkı oranı düşer, başabaş satış miktarı yükselir', ['Katkı oranı yükselir, başabaş satış miktarı azalır', 'Katkı oranı sabit kalır, yalnız başabaş cirosu düşer', 'Hem katkı oranı hem de başabaş miktarı aynı oranda azalır'], 'Satış fiyatının düşmesi birim katkı payını ve katkı oranını küçültür; sabit giderleri çıkarmak için gereken başabaş adedi artar.'),
  ('Gelir tablosunda brüt satışları 1.000.000 TL, satış indirimleri 80.000 TL, SMM 560.000 TL, faaliyet giderleri 210.000 TL ve olağandışı gelirleri 25.000 TL olan işletmenin vergi öncesi kârı (finansman gideri sıfır) kaç TL\'dir?', '175.000 TL', ['150.000 TL', '255.000 TL', '230.000 TL'], 'Net satış = 920.000; Brüt kâr = 920.000 - 560.000 = 360.000; Faaliyet kârı = 360.000 - 210.000 = 150.000; Vergi öncesi kâr = 150.000 + 25.000 = 175.000 TL.'),
  ('Üretimde kullanılan makinelerin çalışma saati üzerinden (üretim miktarı yöntemiyle) amortisman ayrılması durumunda amortisman gideri maliyet davranışı açısından neye dönüşür?', 'Değişken maliyete', ['Sabit maliyete', 'Batık maliyete', 'Finansman giderine'], 'Zaman esasına göre ayrılan amortisman sabit maliyet iken, üretim adedi veya makine saatine göre ayrılan amortisman değişken maliyet niteliği kazanır.'),
  ('Aynı sektörde faaliyet gösteren X şirketinin sabit maliyetleri 300.000 TL ve birim katkı payı 60 TL; Y şirketinin sabit maliyetleri 150.000 TL ve birim katkı payı 30 TL\'dir. İki şirketin başabaş miktarları ve risk yapıları hakkında ne söylenebilir?', 'Başabaş miktarları eşittir ancak X şirketinin faaliyet riski daha yüksektir', ['X şirketinin başabaş miktarı Y şirketinin tam iki katı büyüklüktedir', 'Y şirketi başabaş sonrasında X şirketinden birim başına daha çok kâr eder', 'Sabit maliyetleri farklı olduğundan başabaş miktarları hiçbir zaman eşitlenemez'], 'Her ikisinin başabaş miktarı da 5.000 adettir (300.000/60 = 150.000/30); ancak satışlar 5.000\'in altına düşerse X birim başına 60 TL, Y ise 30 TL zarar yazar.'),
  ('Birim satış fiyatı 160 TL, katkı oranı %45 olan bir üründe birim değişken maliyet kaç TL\'dir?', '88 TL', ['72 TL', '96 TL', '64 TL'], 'Birim katkı payı = 160 x 0,45 = 72 TL; Birim değişken maliyet = 160 - 72 = 88 TL\'dir.'),
  ('Bir işletmenin geçmişte yeni bir ürün geliştirmek için harcadığı ve geri kazanılması mümkün olmayan 500.000 TL\'lik pazar araştırması bedeli, bugünkü fiyatlama kararlarında nasıl değerlendirilmelidir?', 'Batık maliyet olduğundan ileriye dönük kararlarda dikkate alınmamalıdır', ['İlk ay üretilecek ürünlerin birim değişken maliyetine doğrudan eklenmelidir', 'Başabaş analizinde birim katkı payından indirilerek hesaplanmalıdır', 'Dönem sonu mal stoklarının değerini artıran bir unsur olarak yazılmalıdır'], 'Geçmişte yapılmış ve hangi karar alınırsa alınsın geri döndürülemeyen harcamalar batık maliyettir; rasyonel kararlarda dışarıda tutulur.'),
  ('Dönem başı mamul stoku 75.000 TL, dönem içinde üretilen mamullerin maliyeti 525.000 TL ve satılan mamuller maliyeti 490.000 TL ise dönem sonu mamul stoku kaç TL\'dir?', '110.000 TL', ['90.000 TL', '160.000 TL', '40.000 TL'], 'Dönem sonu mamul stoku = Dönem başı stok + Üretilen mamul maliyeti - SMM = 75.000 + 525.000 - 490.000 = 110.000 TL.'),
  ('Normal (eşit paylı) amortisman yöntemi yerine azalan bakiyeler yöntemi seçildiğinde, yatırımın ilk yıllarında işletmenin gelir tablosu nasıl bir farklılık gösterir?', 'Amortisman gideri daha yüksek, vergi öncesi kâr daha düşük raporlanır', ['Amortisman gideri daha düşük, dönem net kârı daha yüksek raporlanır', 'Brüt satış hasılatı hızla artarken satılan malın maliyeti sabit kalır', 'Toplam ekonomik ömür boyunca yazılacak amortisman tutarı iki katına çıkar'], 'Azalan bakiyeler yöntemi ilk yıllarda daha yüksek amortisman ayırarak kârı ve vergiyi ilk yıllarda düşürür; toplam amortisman ise ömür sonunda eşittir.'),
  ('Cari oranı 2,4 iken asit-test oranı 0,6 olarak hesaplanan bir üretim işletmesi hakkında aşağıdaki çıkarımlardan hangisi en doğrudur?', 'Dönen varlıklarının çok büyük bir bölümü stoklardan oluşmaktadır', ['İşletmenin kasasında yüksek miktarda atıl nakit bulunmaktadır', 'Kısa vadeli borçları uzun vadeli borçlarından daha düşüktür', 'Maddi duran varlık yatırımları özsermaye ile finanse edilmiştir'], 'Cari oran yüksekken asit-test oranının çok düşük çıkması, dönen varlıklar içindeki stok payının aşırı yüksek olduğunu gösterir.'),
  ('Toplam aktifleri 1.200.000 TL ve özkaynakları 480.000 TL olan bir şirketin finansal kaldıraç oranı yüzde kaçtır?', '%60', ['%40', '%150', '%25'], 'Toplam borç = Toplam Aktif - Özkaynak = 1.200.000 - 480.000 = 720.000 TL. Finansal kaldıraç = 720.000 / 1.200.000 = 0,60 yani %60\'tır.'),
  ('Gelir tablosunda yüksek net kâr açıklayan bir işletmenin aynı dönemde vadesi gelen faturalarını ödeyememesinin en olası nedeni nedir?', 'Satışların büyük ölçüde uzun vadeli ve henüz tahsil edilmemiş alacaklardan oluşması', ['Amortisman giderlerinin nakit çıkışı gerektiren bir maliyet kalemi olması', 'Şirketin geçmiş yıllar kârlarını yasal yedek akçe olarak ayırmış bulunması', 'Özsermaye tutarının maddi duran varlık toplamından daha yüksek olması'], 'Tahakkuk esasına göre vadeli satış yapıldığında gelir ve kâr yazılır ancak kasaya nakit girmez; bu durum kârlı şirketin nakit sıkışıklığı yaşamasına yol açar.'),
  ('Net satışları 800.000 TL, satışların maliyeti 520.000 TL ve faaliyet giderleri 120.000 TL olan bir işletmenin brüt kâr marjı yüzde kaçtır?', '%35', ['%20', '%65', '%15'], 'Brüt kâr = Net Satışlar - Satışların Maliyeti = 800.000 - 520.000 = 280.000 TL. Brüt kâr marjı = 280.000 / 800.000 = 0,35 yani %35\'tir.'),
  ('Net işletme sermayesi negatif olan bir şirket için aşağıdaki ifadelerden hangisi kesinlikle doğrudur?', 'Cari oranı 1\'in altındadır ve duran varlıklarının bir kısmı kısa vadeli borçla finanse edilmiştir', ['Şirket ilgili hesap döneminde faaliyet zararı açıklamıştır ve özkaynakları tamamen erimiştir', 'Asit-test oranı cari oranından daha büyüktür ve stok devir hızı negatiftir', 'Uzun vadeli yabancı kaynakları toplam aktiflerinden daha yüksek bir tutara ulaşmıştır'], 'Net işletme sermayesi (Dönen Varlıklar - Kısa Vadeli Yabancı Kaynaklar) negatifse dönen varlıklar kısa vadeli borçlardan küçüktür; yani cari oran 1\'den küçüktür.'),
  ('DuPont analizinde özkaynak kârlılığı (ROE) aşağıdaki hangi üç temel bileşenin çarpımı olarak ayrıştırılır?', 'Net kâr marjı, aktif devir hızı ve özkaynak çarpanı', ['Cari oran, stok devir hızı ve brüt satış kâr marjı', 'Asit-test oranı, alacak tahsil süresi ve borç/özkaynak oranı', 'Faaliyet kâr marjı, nakit dönüşüm süresi ve faiz karşılama oranı'], 'DuPont sisteminde ROE = (Net Kâr / Satışlar) x (Satışlar / Toplam Aktif) x (Toplam Aktif / Özkaynak) formülüyle üç bileşene ayrılır.'),
  ('Gelir tablosunda gider olarak düşülen amortisman paylarının, dolaylı yöntemle hazırlanan nakit akış tablosunda net kâra geri eklenmesinin nedeni nedir?', 'Amortismanın işletmeden gerçek bir nakit çıkışına yol açmayan muhasebe gideri olması', ['Amortisman tutarının vergi dairesi tarafından şirkete nakit teşvik olarak iade edilmesi', 'Duran varlıkların her yıl sonunda piyasa değeri üzerinden nakde çevrilmesi', 'Amortismanın finansman faaliyetlerinden sağlanan bir banka kredisi sayılması'], 'Amortisman duran varlık maliyetinin dönemlere yayılmasıdır; ilgili dönemde kasadan para çıkışı yaratmadığı için nakit akışı hesaplanırken net kâra eklenir.'),
  ('Net kârı 240.000 TL, dönem içi amortisman gideri 60.000 TL olan bir şirketin aynı dönemde ticari alacakları 90.000 TL artmış, diğer işletme sermayesi kalemleri değişmemiştir. İşletme faaliyetlerinden net nakit akışı kaç TL\'dir?', '210.000 TL', ['390.000 TL', '270.000 TL', '150.000 TL'], 'İşletme faaliyetlerinden nakit akışı = Net Kâr + Amortisman - Alacaklardaki Artış = 240.000 + 60.000 - 90.000 = 210.000 TL\'dir.'),
  ('Faiz ve vergi öncesi kârı 450.000 TL, yıllık faiz gideri 90.000 TL ve vergi gideri 72.000 TL olan bir işletmenin faiz karşılama oranı kaçtır?', '5,0', ['4,2', '3,2', '6,0'], 'Faiz karşılama oranı = FVÖK / Faiz Giderleri = 450.000 / 90.000 = 5,0 olarak hesaplanır.'),
  ('Peşin parayla ticari mal (stok) satın alan bir işletmenin cari oranı ve asit-test oranı bu işlemden hemen sonra nasıl etkilenir?', 'Cari oran değişmez, asit-test oranı düşer', ['Cari oran düşer, asit-test oranı yükselir', 'Her iki likidite oranı da aynı oranda düşer', 'Her iki likidite oranı da işlem sonrasında değişmez'], 'Kasadaki nakit azalıp aynı tutarda stok arttığı için toplam dönen varlıklar ve cari oran değişmez; ancak stoklar asit-test oranına dahil edilmediğinden asit-test oranı düşer.'),
  ('Brüt kâr marjı geçen yıla göre sabit kalan bir şirketin net kâr marjında sert bir düşüş yaşanmışsa bu durum aşağıdakilerden hangisiyle açıklanabilir?', 'Faaliyet giderlerinin veya finansman (faiz) giderlerinin satışlara oranla artmasıyla', ['Hammadde alış fiyatlarının yükselmesine rağmen satış fiyatlarına yansıtılamamasıyla', 'Üretimde doğrudan çalışan işçilerin saatlik ücretlerinin aşırı yükselmesiyle', 'Satılan ticari malların tedarik maliyetlerinde beklenmedik kur farkı oluşmasıyla'], 'Hammadde ve üretim işçiliği brüt kâr marjını etkiler; brüt marj sabitken net marj düşüyorsa pazarlama, genel yönetim veya finansman/vergi giderleri artmıştır.'),
  ('Toplam borç / Özkaynak oranı 1,5 olan bir şirketin toplam aktifleri 2.500.000 TL ise özkaynakları kaç TL\'dir?', '1.000.000 TL', ['1.500.000 TL', '1.250.000 TL', '1.666.667 TL'], 'Borç / Özkaynak = 1,5 ise Borç = 1,5 x Özkaynak. Toplam Aktif = Borç + Özkaynak = 2,5 x Özkaynak = 2.500.000 TL buradan Özkaynak = 1.000.000 TL bulunur.'),
  ('Bir işletmenin dönem sonunda kasa bakiyesinin artmış olmasına rağmen finansal sağlığının bozulmakta olduğunu aşağıdaki nakit akış tablosu senaryolarından hangisi gösterir?', 'İşletme faaliyetlerinden nakit akışı negatifken yüksek tutarlı duran varlık satışı ve yeni borçlanmayla kasanın dolması', ['İşletme faaliyetlerinden güçlü pozitif nakit üretilirken bu parayla yeni üretim makineleri satın alınması', 'Esas faaliyetlerden sağlanan nakit fazlasıyla vadesi gelen banka kredilerinin anapara taksitlerinin ödenmesi', 'Müşterilerden yapılan peşin tahsilatların artışıyla birlikte ortaklara düzenli temettü ödemesi yapılması'], 'Esas işinden nakit üretemeyen (negatif işletme nakit akışı) bir firmanın fabrikasını satarak veya borçlanarak kasasını doldurması sürdürülebilir değildir.'),
  ('Net satışları 2.000.000 TL, net dönem kârı 160.000 TL, toplam aktifleri 1.000.000 TL olan bir şirketin aktif kârlılığı (ROA) yüzde kaçtır?', '%16', ['%8', '%20', '%32'], 'Aktif kârlılığı (ROA) = Net Dönem Kârı / Toplam Aktifler = 160.000 / 1.000.000 = 0,16 yani %16\'dır.'),
  ('Asit-test oranı hesaplanırken stokların yanı sıra "gelecek aylara ait giderler" (peşin ödenmiş giderler) kaleminin de dönen varlıklardan çıkarılmasının gerekçesi nedir?', 'Peşin ödenmiş giderlerin nakde çevrilemez olması ve yalnızca gelecek dönemlerde hizmet olarak tüketilecek olması', ['Gelecek aylara ait giderlerin gerçekte uzun vadeli bir banka borcu niteliği taşıması', 'Bu kalemin vergi mevzuatına göre bilanço aktifinde değil gelir tablosunda yer alması', 'Peşin ödenen kira veya sigorta poliçelerinin kısa vadeli yabancı kaynak toplamını büyütmesi'], 'Peşin ödenmiş kira veya sigorta gibi kalemler satılıp paraya çevrilecek varlıklar değildir; borç ödemede kullanılamayacakları için likidite oranında düşülür.'),
  ('Dönem içinde stoklarını eritmeyip aksine stok miktarını büyük ölçüde artıran bir üretim işletmesinin nakit akışı bu durumdan nasıl etkilenir?', 'Stoklara bağlanan fonlar nedeniyle işletme faaliyetlerinden nakit akışı azalır', ['Stoklar varlık olduğu için kasadaki nakit bakiyesi aynı tutarda artış gösterir', 'Satılmamış stoklar gelir tablosunda doğrudan net kârı artırdığı için nakit çoğalır', 'Stok artışı yatırım faaliyeti sayıldığından işletme nakit akışı hiç etkilenmez'], 'Stok artışı için nakit harcanır veya borçlanılır ancak henüz satış yapılmadığı için nakit girişi olmaz; bu da işletme nakit akışını azaltır.'),
  ('Dönen varlıkları 600.000 TL (bunun 120.000 TL\'si nakit, 280.000 TL\'si ticari alacak, 200.000 TL\'si stok) ve kısa vadeli borçları 300.000 TL olan işletmenin nakit oranı kaçtır?', '0,40', ['2,00', '1,33', '0,67'], 'Nakit oranı = Nakit ve Nakit Benzerleri / Kısa Vadeli Yabancı Kaynaklar = 120.000 / 300.000 = 0,40 olarak bulunur.'),
  ('Ticari alacaklarını tahsil eden (müşteriden vadesi gelen senedin parasını kasaya alan) bir işletmenin bilançosunda cari oran ve nakit oranı nasıl değişir?', 'Cari oran değişmez, nakit oranı artar', ['Cari oran artar, nakit oranı azalır', 'Her iki oran da aynı miktarda artar', 'Cari oran azalır, nakit oranı değişmez'], 'Alacak tahsil edildiğinde bir dönen varlık (alacak) azalırken diğeri (nakit) aynı tutarda artar; toplam dönen varlık değişmediğinden cari oran sabit kalır, hazır nakit arttığı için nakit oranı yükselir.'),
  ('Satışları 1.500.000 TL, satışların maliyeti 900.000 TL, faaliyet giderleri 300.000 TL, faiz gideri 100.000 TL ve vergi gideri 50.000 TL olan şirketin net kâr marjı yüzde kaçtır?', '%10', ['%20', '%40', '%13,3'], 'Net kâr = 1.500.000 - 900.000 - 300.000 - 100.000 - 50.000 = 150.000 TL. Net kâr marjı = 150.000 / 1.500.000 = %10\'dur.'),
  ('Kısa vadeli banka kredisini kapatmak amacıyla uzun vadeli yeni bir banka kredisi kullanan (borç yapılandırması yapan) işletmenin finansal oranlarında hangi değişim gerçekleşir?', 'Net işletme sermayesi ve cari oran yükselir, toplam finansal kaldıraç oranı değişmez', ['Toplam finansal kaldıraç oranı sıfırlanırken özkaynak kârlılığı iki katına çıkar', 'Cari oran düşerken asit-test oranı ve nakit oranı aynı anda yükselir', 'Dönen varlıklar toplamı artarken maddi duran varlıklar toplamı azalır'], 'Kısa vadeli borç azalıp aynı tutarda uzun vadeli borç arttığı için toplam borç (ve kaldıraç oranı) değişmez; ancak kısa vadeli borç düştüğü için net işletme sermayesi ve cari oran artar.'),
  ('Bir perakende zincirinin "negatif nakit dönüşüm süresi" ile çalışması aşağıdakilerden hangisiyle mümkün olur?', 'Müşterilerden peşin tahsilat yapıp tedarikçilerine uzun vadeli ödeme yapmasıyla', ['Stoklarını depoda ortalama bir yıldan uzun süre bekleterek satmasıyla', 'Tüm mal alımlarını peşin ödeyip müşterilerine 12 ay taksitle satış yapmasıyla', 'Kısa vadeli ticari borçlarının tamamını özsermaye artırımıyla kapatmasıyla'], 'Peşin satıp stokları hızla eriten ve tedarikçiye 60-90 gün vadeli ödeyen market zincirlerinde borç ödeme süresi, stok ve alacak süresinin toplamından büyük olur; böylece negatif nakit dönüşüm süresi oluşur.'),
  ('Negatif finansal kaldıraç etkisi (borçlanmanın özkaynak kârlılığını düşürmesi) hangi koşul gerçekleştiğinde ortaya çıkar?', 'Varlıkların vergi ve faiz öncesi getiri oranı borçlanma faiz maliyetinin altına düştüğünde', ['Şirketin net satış hasılatı bir önceki döneme kıyasla enflasyonun üzerinde arttığında', 'Müşterilerden olan ticari alacakların tahsil süresi tedarikçi vadesinden kısa olduğunda', 'İşletmenin cari oranı 2,0 seviyesinin üzerinde istikrarlı biçimde seyrettiğinde'], 'İşletme borçla aldığı kaynakla faiz maliyetinden daha düşük bir faaliyet getirisi elde ediyorsa aradaki fark özkaynak sahiplerinin getirisinden gider ve ROE düşer.'),
  ('Dönem başı nakit mevcudu 80.000 TL olan bir işletmenin dönem içinde işletme faaliyetlerinden nakit akışı +300.000 TL, yatırım faaliyetlerinden nakit akışı -220.000 TL ve finansman faaliyetlerinden nakit akışı -50.000 TL olmuştur. Dönem sonu nakit mevcudu kaç TL\'dir?', '110.000 TL', ['30.000 TL', '510.000 TL', '210.000 TL'], 'Net nakit değişimi = 300.000 - 220.000 - 50.000 = +30.000 TL. Dönem sonu nakit = Dönem başı nakit + Net değişim = 80.000 + 30.000 = 110.000 TL\'dir.'),
  ('Cari oranı 2,5 ve asit-test oranı 1,5 olan bir işletmenin stokları 400.000 TL ise kısa vadeli yabancı kaynakları kaç TL\'dir?', '400.000 TL', ['600.000 TL', '1.000.000 TL', '250.000 TL'], 'Cari oran - Asit-test oranı = Stoklar / Kısa Vadeli Yabancı Kaynaklar. 2,5 - 1,5 = 1,0 = 400.000 / KVYK buradan KVYK = 400.000 TL bulunur.'),
  ('Yıl sonunda ortaklarına yüksek tutarda nakit temettü (kâr payı) ödeyen bir şirketin hemen bu ödeme sonrasında cari oranı ve finansal kaldıraç oranı nasıl etkilenir?', 'Cari oran düşer, finansal kaldıraç oranı yükselir', ['Cari oran yükselir, finansal kaldıraç oranı düşer', 'Cari oran değişmez, finansal kaldıraç oranı düşer', 'Her iki oran da temettü ödemesinden etkilenmez'], 'Nakit temettü ödendiğinde kasadaki nakit (dönen varlık) azalır, bu yüzden cari oran düşer; aynı zamanda özkaynak ve toplam aktif azaldığı için (borç sabitken aktif küçüldüğünden) Borç/Aktif yani kaldıraç oranı yükselir.'),
  ('Müşterilerine yaptığı vadeli satışlarda tahsilat sorunu yaşayan ancak şüpheli alacak karşılığı ayırmayı ihmal eden bir şirketin finansal tablolarında hangi yanıltıcı tablo oluşur?', 'Cari oran, asit-test oranı ve dönem kârı gerçekte olduğundan daha yüksek görünür', ['Nakit oranı gerçek değerinin çok üzerinde hesaplanırken borçlar gizlenmiş olur', 'İşletme faaliyetlerinden nakit akışı tahsil edilmeyen alacaklar kadar fazla raporlanır', 'Finansal kaldıraç oranı olduğundan yüksek görünürken özkaynaklar eksik yazılır'], 'Tahsil edilemeyen alacaklar karşılık ayrılmazsa dönen varlıklarda tam değerle kalır ve gider yazılmaz; böylece hem likidite oranları (cari ve asit-test) hem de kâr yapay olarak yüksek görünür.'),
  ('Bir yazılım şirketi ile bir demir-çelik fabrikasının bilançoları incelendiğinde yazılım şirketinde asit-test oranının cari orana neredeyse eşit çıkmasının temel sebebi nedir?', 'Yazılım şirketinin fiziksel stok bulundurmaması veya stoklarının ihmal edilecek kadar az olması', ['Yazılım sektöründe kısa vadeli yabancı kaynak kullanımının yasal olarak bulunmaması', 'Demir-çelik fabrikalarının tüm satışlarını peşin yapıp hiç ticari alacak taşımaması', 'Yazılım şirketlerinin kasasında hiç nakit tutmayıp tüm varlığını arsalara yatırması'], 'Fiziksel mal üretmeyen veya alıp satmayan hizmet/yazılım işletmelerinde stok kalemi neredeyse sıfırdır; bu nedenle (Dönen Varlıklar - Stoklar) doğrudan Dönen Varlıklara eşit olur.'),
  ('Özkaynak çarpanı 2,5 olan bir işletmenin finansal kaldıraç oranı (Toplam Borç / Toplam Aktif) yüzde kaçtır?', '%60', ['%40', '%25', '%75'], 'Aktif / Özkaynak = 2,5 ise Özkaynak / Aktif = 1 / 2,5 = 0,40 (%40) olur. Geriye kalan %60 ise yabancı kaynak (borç) payıdır.'),
  ('İşletme sermayesi yönetiminde "ihtiyatlı (muhafazakâr) finansman stratejisi" izleyen bir finans yöneticisi aşağıdakilerden hangisini tercih eder?', 'Dönen varlıkların tamamını ve hatta geçici dalgalanmaların bir kısmını uzun vadeli kaynaklarla finanse etmeyi', ['Duran varlık yatırımlarının tamamını gecelik ve çok kısa vadeli banka kredileriyle finanse etmeyi', 'Kasadaki nakit bakiyesini sıfırda tutarak tedarikçi ödemelerini sürekli geciktirmeyi', 'Net işletme sermayesini negatif bölgede tutarak faiz maliyetini en aza indirmeyi'], 'İhtiyatlı stratejide likidite riskinden kaçınmak için uzun vadeli kaynaklar yoğun kullanılır, net işletme sermayesi ve cari oran yüksek tutulur.'),
  ('Aktif kârlılığı (ROA) %8 olan ve toplam varlıklarının %60\'ını özkaynaklarla, %40\'ını yabancı kaynaklarla finanse eden bir şirketin özkaynak kârlılığı (ROE) kaçtır?', '%13,33', ['%12,00', '%20,00', '%4,80'], 'ROE = ROA / (Özkaynak / Toplam Aktif) = %8 / 0,60 = %13,33 olarak hesaplanır.'),
  ('Gelir tablosunda yüksek kâr açıklayan bir inşaat taahhüt firmasının banka hesaplarında nakit kalmamasının en yaygın operasyonel nedeni aşağıdakilerden hangisidir?', 'Hak ediş faturalarının kesilip gelir yazılmasına rağmen işverenden tahsilatın aylar sonra yapılması', ['Şirketin merkez ofis kirası için uzun vadeli finansal kiralama sözleşmesi imzalamaması', 'İnşaat demiri ve çimento tedarikçilerine ödemelerin 120 gün vadeli çeklerle yapılması', 'Geçmiş yıllarda alınan iş makineleri için ayrılan amortisman oranının yüksek tutulması'], 'Fatura kesildiğinde (hak ediş onaylandığında) gelir ve kâr tahakkuk eder; ancak malzeme ve işçilik peşin ödenirken tahsilat geciktiğinde ciddi nakit sıkışıklığı doğar.'),
  ('Özsermaye ile finansman yerine banka kredisi kullanmanın vergi kalkanı avantajı sağlamasına rağmen şirketlerin %100 borçla çalışmamasının temel nedeni nedir?', 'Borç arttıkça finansal sıkıntı, iflas maliyetleri ve kreditörlerin talep ettiği faiz oranının hızla yükselmesi', ['Kurumlar vergisi kanununa göre banka kredisi kullanan şirketlerin ihracat yapmasının yasaklanması', 'Borçlanma oranı %50\'yi geçtiğinde cari oranın matematiksel olarak negatif sayıya dönüşmesi', 'Yabancı kaynak kullanımının şirketin brüt satış hasılatını doğrudan doğruya azaltması'], 'Aşırı borçlanma finansal risk ve iflas olasılığını büyütür; borç verenler daha yüksek risk primi (faiz) ister ve bir noktadan sonra borcun maliyeti vergi avantajını aşar.'),
  ('Yeni hisse senedi ihraç ederek ortaklardan nakit sermaye toplayan bir şirketin likidite ve kaldıraç oranları bu işlemden hemen sonra nasıl etkilenir?', 'Likidite oranları yükselir, finansal kaldıraç oranı düşer', ['Likidite oranları düşer, finansal kaldıraç oranı yükselir', 'Her iki oran grubu da aynı yönde yükselir', 'Likidite oranları değişmez, kaldıraç oranı sıfırlanır'], 'Kasaya nakit girdiği için dönen varlıklar ve tüm likidite oranları artar; toplam borç sabitken özkaynak ve toplam aktif büyüdüğü için Borç/Aktif (kaldıraç) oranı düşer.'),
  ('Cari oranı 1,6 ve net işletme sermayesi 240.000 TL olan bir şirketin dönen varlıkları toplamı kaç TL\'dir?', '640.000 TL', ['400.000 TL', '384.000 TL', '840.000 TL'], 'Dönen Varlıklar = 1,6 x KVYK. Net İşletme Sermayesi = 1,6 KVYK - KVYK = 0,6 KVYK = 240.000 TL buradan KVYK = 400.000 TL ve Dönen Varlıklar = 1,6 x 400.000 = 640.000 TL bulunur.'),
  ('Bir şirketin dönem sonunda satıcılarına olan vadesi gelmiş 150.000 TL\'lik borcunu kasadaki nakitle ödemesi net işletme sermayesini nasıl etkiler?', 'Net işletme sermayesi tutar olarak hiç değişmez', ['Net işletme sermayesi 150.000 TL tutarında artar', 'Net işletme sermayesi 150.000 TL tutarında azalır', 'Net işletme sermayesi yarı yarıya küçülür'], 'Dönen varlıklar (kasa) 150.000 TL azalırken kısa vadeli yabancı kaynaklar (satıcılar) da 150.000 TL azalır; ikisi arasındaki fark olan net işletme sermayesi sabit kalır.'),
  ('Dolaylı yöntemle hazırlanan nakit akış tablosunda amortisman giderinin net kâra yeniden eklenmesinin temel nedeni nedir?', 'Nakit çıkışı gerektirmediği hâlde kârı azaltması', ['Dönem sonunda nakit girişi yaratan bir gelir sayılması', 'Vergi dairesinden doğrudan nakit iadesi sağlaması', 'Sadece finansman faaliyetlerine ait bir kalem olması'], 'Amortisman gelir tablosunda gider olarak net kârı düşürür ancak fiilî nakit çıkışı yaratmadığı için nakit akışı hesaplanırken geri eklenir.'),
  ('Bir işletmenin işletme faaliyetlerinden net nakit girişi 180.000 TL, yatırım faaliyetlerinden net nakit çıkışı 120.000 TL ve finansman faaliyetlerinden net nakit çıkışı 25.000 TL ise dönemdeki net nakit değişimi nedir?', '35.000 TL artış', ['85.000 TL nakit artışı', '60.000 TL nakit azalışı', '325.000 TL nakit artışı'], 'Net nakit değişimi üç faaliyetin cebirsel toplamıdır: 180.000 − 120.000 − 25.000 = +35.000 TL artış.'),
  ('Bir şirketin gelir tablosunda yüksek net kâr görünmesine rağmen işletme faaliyetlerinden nakit akışının negatif olmasının en olası nedeni hangisidir?', 'Alacakların ve stokların hızla artması', ['Müşterilerin peşin ödeme oranını yükseltmesi', 'Tedarikçilere olan ödeme vadesinin uzaması', 'Sabit varlıkların peşin bedelle satılması'], 'Kredili satışlar tahsil edilmeden kâr yazıldığında alacaklar büyür, stok birikimi de nakdi bağlayarak işletme nakit akışını negatife çekebilir.'),
  ('Dolaylı yöntemde dönem boyunca ticari alacakların artması, işletme faaliyetlerinden nakit akışı hesaplanırken nasıl dikkate alınır?', 'Net kârdan düşülür', ['Net kâra doğrudan ilave edilir', 'Yatırım faaliyetlerine nakit çıkışı yazılır', 'Finansman faaliyetlerine nakit girişi yazılır'], 'Ticari alacakların artması, gelirin kayda alındığını ancak nakdin henüz tahsil edilmediğini gösterdiği için net kârdan indirilir.'),
  ('Dolaylı yöntemde dönem içinde ticari borçların artması işletme faaliyetlerinden nakit akışını nasıl etkiler?', 'Net kâra eklenir', ['Net kârdan doğrudan çıkarılır', 'Yatırım faaliyetlerinden nakit çıkışı sayılır', 'Nakit akış tablosunda hiçbir yerde görünmez'], 'Ticari borçların artması tedarikçilere henüz ödeme yapılmayıp nakdin işletmede kaldığını ifade ettiğinden net kâra eklenir.'),
  ('Serbest nakit akışı (Free Cash Flow) en yaygın pratik yaklaşımla hangi iki kalemin farkı olarak hesaplanır?', 'İşletme nakit akışı eksi sermaye harcamaları', ['Brüt satış kârı eksi toplam vergi gideri', 'Toplam varlıklar eksi kısa vadeli borçlar', 'Finansman nakit girişi eksi nakit temettü'], 'Serbest nakit akışı, işletmenin faaliyetlerinden ürettiği nakitten mevcut kapasiteyi korumak veya büyütmek için yaptığı sermaye harcamalarının (CAPEX) çıkarılmasıyla bulunur.'),
  ('İşletmenin tedarikçilere hammadde alımı için yaptığı peşin ödemeler nakit akış tablosunun hangi bölümünde yer alır?', 'İşletme faaliyetleri', ['Yatırım faaliyetleri nakit çıkışı', 'Finansman faaliyetleri nakit çıkışı', 'Sermaye yedekleri azalış hesabı'], 'Mal ve hizmet üretimi için tedarikçilere ödenen nakit tutarlar işletme faaliyetlerinden nakit çıkışlarını oluşturur.'),
  ('Dönen varlıkları 600.000 TL, stokları 240.000 TL ve kısa vadeli borçları 300.000 TL olan bir şirketin asit-test oranı kaçtır?', '1,20', ['2,00 likidite oranı', '0,80 likidite oranı', '1,50 likidite oranı'], 'Asit-test oranı = (600.000 − 240.000) / 300.000 = 360.000 / 300.000 = 1,20 olarak bulunur.'),
  ('Bir şirketin cari oranı 2,40 iken asit-test oranının 0,65 olması finansal analiste hangi önemli işareti verir?', 'Dönen varlıkların büyük kısmının stoklara bağlı olduğu', ['Kısa vadeli borçların tamamının kasa nakdiyle karşılandığı', 'Şirketin hiç ticari borç kullanmadığı', 'Uzun vadeli kredilerin özkaynakları aştığı'], 'Cari oran ile asit-test oranı arasındaki geniş fark, dönen varlıkların çok büyük bir bölümünün stoklardan oluştuğunu gösterir.'),
  ('Toplam varlıkları 1.000.000 TL ve özkaynakları 400.000 TL olan bir işletmenin borç/özkaynak oranı kaçtır?', '1,50', ['0,60 kaldıraç oranı', '2,50 kaldıraç oranı', '0,40 kaldıraç oranı'], 'Bilanço eşitliğinden Toplam Borç = 1.000.000 − 400.000 = 600.000 TL\'dir. Borç/özkaynak = 600.000 / 400.000 = 1,50 olur.'),
  ('Bir şirketin borç/özkaynak oranının sektör ortalamasının çok üzerinde olması öncelikle hangi riskin yükseldiğine işaret eder?', 'Finansal riskin', ['Döviz fazlası elde etme riskinin', 'Stok devir hızının sıfırlanma riskinin', 'Amortisman oranının düşme riskinin'], 'Borç yükünün özkaynaklara kıyasla aşırı artması, sabit faiz ve ana para yükümlülükleri nedeniyle finansal riski ve ödeme güçlüğü olasılığını yükseltir.'),
  ('Faiz karşılama oranı hesaplanırken faiz giderlerine hangi gelir tablosu büyüklüğü bölünür?', 'Faiz ve vergi öncesi kâr', ['Net satış hasılatı toplamı', 'Dönem sonu birikmiş amortisman tutarı', 'Kısa vadeli ticari borç bakiyesi'], 'Faiz karşılama oranı = FVÖK (Faaliyet Kârı) / Faiz Giderleri formülüyle şirketin faaliyet kazancıyla faiz yükünü kaç kez karşılayabildiğini ölçer.'),
  ('Faaliyet kârı (FVÖK) 450.000 TL ve yıllık faiz gideri 90.000 TL olan bir işletmenin faiz karşılama oranı kaçtır?', '5', ['4 kat faiz karşılama', '6 kat faiz karşılama', '0,20 faiz karşılama'], 'Faiz karşılama oranı = 450.000 / 90.000 = 5 olarak hesaplanır; işletme faiz yükünün 5 katı faaliyet kârı üretmektedir.'),
  ('Yıllık satışların maliyeti 720.000 TL ve ortalama stok tutarı 120.000 TL olan bir şirketin stok devir hızı ve 360 günlük yıla göre ortalama stokta kalma süresi nedir?', '6 kez ve 60 gün', ['6 kez ve 90 gün kalma süresi', '4 kez ve 90 gün kalma süresi', '8 kez ve 45 gün kalma süresi'], 'Stok devir hızı = 720.000 / 120.000 = 6 kez; stokta kalma süresi = 360 / 6 = 60 gündür.'),
  ('Yıllık kredili satışları 900.000 TL ve ortalama ticari alacakları 150.000 TL olan işletmenin 360 günlük yıla göre ortalama tahsil süresi kaç gündür?', '60 gün', ['45 gün tahsil süresi', '75 gün tahsil süresi', '90 gün tahsil süresi'], 'Alacak devir hızı = 900.000 / 150.000 = 6 kez; ortalama tahsil süresi = 360 / 6 = 60 gün olur.'),
  ('Aktif devir hızı (toplam varlık devir hızı) hangi finansal verimlilik göstergesini ölçer?', 'Varlıkların ne kadar satış hasılatı ürettiğini', ['Borçların ne kadar vergi tasarrufu sağladığını', 'Kasa nakdinin kısa vadeli borçlara oranını', 'Brüt kârın faaliyet giderlerine oranını'], 'Aktif devir hızı = Net Satışlar / Ortalama Toplam Varlıklar formülüyle işletmenin her 1 TL\'lik varlıkla kaç TL satış ürettiğini gösterir.'),
  ('Bir işletmenin cari oranı 1,50 iken kasadaki nakitle kısa vadeli ticari borçlarının bir kısmını ödemesi cari oranı nasıl etkiler?', 'Cari oran artar', ['Cari oran azalır ve 1\'in altına iner', 'Cari oran kesinlikle değişmeden kalır', 'Cari oran doğrudan sıfıra eşitlenir'], 'Pay ve paydadan aynı tutar çıkarıldığında başlangıç oranı 1\'den büyükse kesrin değeri büyür; dolayısıyla cari oran yükselir.'),
  ('İlgili faaliyet aralığında üretim miktarı arttıkça birim başına sabit maliyet nasıl değişir?', 'Azalır', ['Üretimle orantılı olarak yükselir', 'Her üretim düzeyinde sabit kalır', 'Önce sıfırlanır sonra negatife döner'], 'Toplam sabit maliyet daha fazla ürün birimine bölündüğü için birim sabit maliyet üretim arttıkça düşer (ölçek ekonomisi etkisi).'),
  ('İlgili faaliyet aralığında üretim miktarı arttığında birim başına değişken maliyetin teorik olarak nasıl davranması beklenir?', 'Sabit kalır', ['Üretim arttıkça hızla sıfıra yaklaşır', 'Toplam sabit maliyet kadar artar', 'Her birim artışta yarıya düşer'], 'Toplam değişken maliyet üretim miktarıyla orantılı arttığı için birim başına değişken maliyet ilgili aralıkta sabit kabul edilir.'),
  ('Katkı payı oranı %40 ve aylık toplam sabit maliyetleri 120.000 TL olan bir işletmenin başabaş satış tutarı (cirosu) kaç TL\'dir?', '300.000 TL', ['480.000 TL satış tutarı', '200.000 TL satış tutarı', '168.000 TL satış tutarı'], 'Başabaş satış tutarı = Sabit Maliyet / Katkı Payı Oranı = 120.000 / 0,40 = 300.000 TL olarak hesaplanır.'),
  ('Mevcut veya planlanan satışların başabaş satış düzeyini aşan kısmına maliyet-hacim-kâr analizinde ne ad verilir?', 'Güvenlik marjı', ['Faaliyet gider oranı', 'Brüt kâr çarpanı', 'Katkı payı açığı'], 'Güvenlik marjı, işletmenin zarara girmeden satışlarında katlanabileceği maksimum düşüş tutarını veya oranını gösterir.'),
  ('Maliyet yapısında sabit maliyetlerin payı yüksek olan bir işletme için faaliyet kaldıracı (işletme kaldıracı) hakkında ne söylenebilir?', 'Faaliyet kaldıracı yüksektir', ['Faaliyet kaldıracı her zaman sıfırdır', 'Satış değişimleri kârı hiç etkilemez', 'Başabaş noktası her zaman çok düşüktür'], 'Sabit maliyet ağırlığı arttıkça satış hacmindeki yüzdelik değişimin faaliyet kârında yarattığı yüzdelik etki büyür; yani faaliyet kaldıracı yükselir.'),
  ('Toplam katkı payı 360.000 TL ve faaliyet kârı (FVÖK) 120.000 TL olan bir işletmenin faaliyet kaldıracı derecesi (DOL) kaçtır?', '3', ['2 faaliyet kaldıracı', '4 faaliyet kaldıracı', '0,33 faaliyet kaldıracı'], 'Faaliyet kaldıracı derecesi = Toplam Katkı Payı / Faaliyet Kârı = 360.000 / 120.000 = 3 olarak hesaplanır.'),
  ('Daha önce katlanılmış ve alınacak yeni bir yönetim kararıyla değiştirilmesi mümkün olmayan geçmiş maliyetlere ne ad verilir?', 'Batık maliyet', ['Fırsat seçim maliyeti', 'Ek marjinal üretim maliyeti', 'Değişken işçilik maliyeti'], 'Geçmişte harcanmış ve geri döndürülemez olan batık maliyetler gelecek odaklı ekonomik kararlarda dikkate alınmamalıdır.'),
  ('Maliyeti 220.000 TL, kalıntı (hurda) değeri 20.000 TL ve faydalı ömrü 5 yıl olan bir makinenin doğrusal yöntemle yıllık amortisman gideri kaç TL\'dir?', '40.000 TL', ['44.000 TL yıllık amortisman', '48.000 TL yıllık amortisman', '50.000 TL yıllık amortisman'], 'Doğrusal yıllık amortisman = (220.000 − 20.000) / 5 = 200.000 / 5 = 40.000 TL olarak hesaplanır.'),
  ('Maliyeti 100.000 TL ve normal amortisman oranı %20 (5 yıl) olan bir makineye çift katlı azalan bakiyeler (%40) yöntemi uygulanırsa ikinci yıl amortisman gideri kaç TL olur?', '24.000 TL', ['40.000 TL ikinci yıl amortismanı', '20.000 TL ikinci yıl amortismanı', '32.000 TL ikinci yıl amortismanı'], 'İlk yıl amortismanı = 100.000 × %40 = 40.000 TL; kalan net defter değeri = 60.000 TL; ikinci yıl amortismanı = 60.000 × %40 = 24.000 TL olur.'),
  ('Maliyet bedeli 350.000 TL ve birikmiş amortismanı 140.000 TL olan bir üretim makinesinin bilançodaki net defter değeri kaç TL\'dir?', '210.000 TL', ['490.000 TL net defter değeri', '140.000 TL net defter değeri', '350.000 TL net defter değeri'], 'Net defter değeri = Maliyet Bedeli − Birikmiş Amortisman = 350.000 − 140.000 = 210.000 TL olarak bulunur.'),
  ('Bir işletme 1 Temmuz tarihinde 12 aylık işyeri sigorta poliçesi için 24.000 TL peşin öderse tahakkuk esasına göre o yılın gelir tablosuna kaç TL sigorta gideri yazılmalıdır?', '12.000 TL', ['24.000 TL sigorta gideri', '6.000 TL sigorta gideri', '18.000 TL sigorta gideri'], 'Poliçenin sadece 1 Temmuz–31 Aralık arasındaki 6 ayı cari yıla ait olduğundan 24.000 × (6/12) = 12.000 TL gider yazılır, kalan 12.000 TL gelecek aylara ait gider (varlık) olarak bilançoda kalır.'),
  ('Dönem sonunda çalışanların hak ettiği ancak maaş ödemesi ertesi ayın başında yapılacak ücretlerin cari yıl giderlerine kaydedilmesi hangi esasa dayanır?', 'Tahakkuk esası', ['Nakit esası kayıt yaklaşımı', 'Tarihî maliyet ölçüm esası', 'Hızlandırılmış amortisman yöntemi'], 'İşçilik hizmeti cari dönemde alındığı için ödeme sonraki ayda yapılsa dahi ücret gideri tahakkuk esası gereği cari döneme yazılır ve ödenecek gider borcu oluşturulur.'),
  ('Bir makinenin faydalı ömrü boyunca tüm amortisman yöntemleriyle ayrılacak toplam amortisman tutarı hakkında hangi ifade doğrudur?', 'Tüm yöntemlerde toplam amortisman aynıdır', ['Azalan bakiyelerde toplam amortisman iki katıdır', 'Doğrusal yöntemde toplam amortisman daha büyüktür', 'Üretim miktarı yönteminde maliyet aşılır'], 'Hangi yöntem seçilirse seçilsin, bir varlık için ömrü boyunca ayrılan toplam amortisman "Maliyet Bedeli − Kalıntı Değer" tutarına eşittir; yöntemler sadece yıllara dağılımı değiştirir.'),
  ('Net işletme sermayesi (net çalışma sermayesi) hangi iki bilanço kalemi arasındaki farkı ifade eder?', 'Dönen varlıklar eksi kısa vadeli borçlar', ['Toplam varlıklar eksi toplam özkaynaklar', 'Duran varlıklar eksi uzun vadeli borçlar', 'Hazır değerler eksi ticari alacaklar'], 'Net işletme sermayesi = Dönen Varlıklar − Kısa Vadeli Yabancı Kaynaklar şeklinde tanımlanır ve günlük faaliyetler için tampon likiditeyi gösterir.'),
  ('Bir işletmenin cari oranının 1,00\'in altında olması net işletme sermayesi açısından doğrudan ne anlama gelir?', 'Net işletme sermayesinin negatif olduğu', ['Dönen varlıkların uzun vadeli borçları aştığı', 'İşletmenin hiç duran varlığa sahip olmadığı', 'Özkaynakların sıfırın altına gerilediği'], 'Cari oran < 1 ise Dönen Varlıklar < Kısa Vadeli Borçlar demektir; bu durumda net işletme sermayesi negatiftir.'),
  ('Aktif kârlılığı (ROA) oranı ile özkaynak kârlılığı (ROE) oranı arasındaki temel kavramsal fark nedir?', 'ROA tüm varlıkların, ROE ortakların sermayesinin getirisini ölçer', ['ROA yalnız kısa vadeli borçların, ROE stokların getirisini ölçer', 'ROA brüt satışları, ROE sadece nakit akışını paya yazar', 'ROA vergi öncesi kârla, ROE yalnız amortismanla hesaplanır'], 'ROA = Net Kâr / Toplam Varlıklar tüm kaynakların verimliliğini; ROE = Net Kâr / Özkaynaklar ise hissedarların yatırdığı sermayenin getirisini ölçer.'),
  ('Bir makinenin normal bakım-onarım gideri ile makinenin kapasitesini veya ekonomik ömrünü kalıcı olarak artıran büyük revizyon harcaması muhasebede nasıl ayrıştırılır?', 'Bakım dönem gideri, revizyon varlık maliyeti yazılır', ['Her ikisi de doğrudan özkaynaklardan indirilir', 'Bakım aktifleştirilir, revizyon dönem gideri yazılır', 'Her ikisi de yalnız nakit akışında gösterilir'], 'Rutin bakım-onarım mevcut durumu koruduğu için doğrudan giderleştirilir; ömrü veya kapasiteyi artıran harcamalar ise varlığın maliyetine eklenerek amortismana tabi tutulur.'),
  ('Özkaynaklar grubunda yer alan "geçmiş yıllar kârları" (dağıtılmamış kârlar) hesabı neyi temsil eder?', 'Ortaklara dağıtılmayıp işletmede bırakılan birikimli kârları', ['İşletmenin bankadaki nakit mevduatının tam karşılığını', 'Sadece içinde bulunulan yılın brüt satış hasılatını', 'Kısa vadeli tedarikçi borçlarının ertelenmiş kısmını'], 'Dağıtılmamış kârlar, geçmiş dönemlerde elde edilen net kârlardan temettü olarak dağıtılmayıp özsermayeyi büyütmek üzere bünyede tutulan tutarlardır.'),
  ('Dönem başı dağıtılmamış kârı 150.000 TL olan bir şirket yıl içinde 90.000 TL net kâr elde edip ortaklarına 35.000 TL temettü dağıtırsa dönem sonu dağıtılmamış kârı kaç TL olur?', '205.000 TL', ['275.000 TL dağıtılmamış kâr', '115.000 TL dağıtılmamış kâr', '185.000 TL dağıtılmamış kâr'], 'Dönem sonu dağıtılmamış kâr = 150.000 + 90.000 − 35.000 = 205.000 TL olarak hesaplanır.'),
  ('Fiyatların sürekli yükseldiği (enflasyonist) bir ortamda FIFO yöntemi ağırlıklı ortalama maliyet yöntemine göre dönem sonu stoklarını ve brüt kârı nasıl etkiler?', 'Stoklar ve brüt kâr daha yüksek çıkar', ['Stoklar yüksek, brüt kâr daha düşük çıkar', 'Stoklar düşük, satışların maliyeti yüksek çıkar', 'Stoklar ve brüt kâr tamamen eşit çıkar'], 'Enflasyonist ortamda FIFO eski ve ucuz maliyetleri satılan malın maliyetine, yeni ve pahalı alımları stoklara yazdığı için hem dönem sonu stoğu hem brüt kâr daha yüksek görünür.'),
  ('Muhasebede "ihtiyatlılık (tutuculuk) kavramı" neyi gerektirir?', 'Olası zararlar için karşılık ayırıp gerçekleşmemiş kârları yazmamayı', ['Tüm gelirleri tahsil edilmeden peşinen yüksek göstermeyi', 'Duran varlıkları her ay piyasa fiyatına göre şişirmeyi', 'Borçları bilançoda mümkün olduğunca gizli tutmayı'], 'İhtiyatlılık gereği muhtemel gider ve zararlar için karşılık ayrılırken, kesinleşmemiş gelir ve kârlar finansal tablolara yansıtılmaz.'),
  ('"Dönemsellik kavramı" ile "eşleştirme (gelir-gider karşılaştırma) ilkesi" arasındaki ilişki nedir?', 'Gelirler, kendilerini doğuran giderlerle aynı döneme yazılır', ['Tüm nakit girişleri mutlaka gelecek yıla ertelenir', 'Giderler yalnız yıl sonunda topluca özkaynağa eklenir', 'Gelir ve giderler birbirinden bağımsız yıllarda izlenir'], 'Eşleştirme ilkesi gereği bir dönemin hasılatını elde etmek için katlanılan maliyet ve giderler aynı hesap döneminde eşleştirilerek gerçek kâr bulunur.'),
  ('Bir şirketin önceki yıllarla karşılaştırılabilirlik sağlamak için seçtiği amortisman veya stok değerleme yöntemini geçerli gerekçe olmadan sık sık değiştirmemesi hangi kavramın gereğidir?', 'Tutarlılık kavramı', ['Özün önceliği ilkesi', 'Tarafsızlık ve belgelendirme', 'Parayla ölçülme kavramı'], 'Tutarlılık ilkesi, finansal tabloların dönemler arası anlamlı biçimde kıyaslanabilmesi için muhasebe politikalarının sürekliliğini öngörür.'),
  ('Finansal kiralamayla (leasing) edinilen bir makinenin hukuki mülkiyeti henüz kiralayanda olsa bile kullanım risk ve getirileri kiracıya geçtiği için kiracının bilançosunda varlık olarak gösterilmesi hangi ilkeye dayanır?', 'Özün önceliği', ['Tarihî maliyet esası', 'Nakit tahsilat esası', 'Maliyet-hacim eşleştirmesi'], 'Özün önceliği kavramı, işlemlerin muhasebeleştirilmesinde hukuki biçimden çok ekonomik gerçeğin esas alınmasını gerektirir.'),
  ('Trend (eğilim yüzdeleri) analizinde baz yıl (temel yıl) kalemleri hangi değere eşitlenerek sonraki yılların gelişimi izlenir?', '100', ['10 baz endeks değeri', '0 başlangıç baz değeri', '1.000 dönem baz değeri'], 'Trend analizinde normal faaliyet koşullarını yansıtan bir baz yıl 100 kabul edilir ve takip eden yıllardaki kalemler buna oranlanarak uzun vadeli eğilim izlenir.'),
  ('Gelir tablosunda dikey analiz yapılırken net satışlar 1.000.000 TL, satışların maliyeti 620.000 TL ve net dönem kârı 80.000 TL ise satışların maliyeti ile net kârın dikey yüzdeleri nedir?', '%62 ve %8', ['%62 ve %38 dikey yüzdesi', '%38 ve %8 dikey yüzdesi', '%77,5 ve %12,9 dikey yüzdesi'], 'Gelir tablosu dikey analizinde net satışlar %100 kabul edilir: Satışların maliyeti 620.000 / 1.000.000 = %62, net kâr 80.000 / 1.000.000 = %8 olur.'),
  ('Maliyet muhasebesinde fabrika ustabaşının maaşı, fabrika elektriği ve üretim makinelerinin amortismanı hangi maliyet grubunda sınıflandırılır?', 'Genel üretim giderleri', ['Direkt ilk madde ve malzeme', 'Genel yönetim dönem giderleri', 'Finansman faiz maliyetleri'], 'Üretimle doğrudan ilgili olup tek bir mamule doğrudan yüklenemeyen fabrika giderleri genel üretim giderleri (GÜG) içinde toplanır.'),
  ('Tam maliyet yöntemi ile değişken maliyet yöntemi arasındaki temel ayrım hangi maliyet kaleminin ürün maliyetine dâhil edilip edilmemesinden kaynaklanır?', 'Sabit genel üretim giderleri', ['Direkt hammadde malzeme maliyeti', 'Direkt üretim işçilik ücreti', 'Satış temsilcisi prim gideri'], 'Tam maliyet yönteminde sabit genel üretim giderleri ürün maliyetine (stoklara) yüklenirken, değişken maliyet yönteminde doğrudan dönem gideri yazılır.'),
  ('Toplam üretim miktarının bir birim artırılması durumunda toplam maliyette meydana gelen ek değişime ne ad verilir?', 'Marjinal maliyet', ['Ortalama sabit birim maliyet', 'Toplam genel yönetim maliyeti', 'Birikmiş amortisman maliyeti'], 'Marjinal maliyet, ilave bir birim daha üretmenin toplam maliyete getirdiği artıştır ve kısa vadede değişken maliyet davranışını yansıtır.'),
  ('Bir şirket A ürününde birim katkı payı 30 TL (satış karışımı %60) ve B ürününde birim katkı payı 50 TL (satış karışımı %40) ile çalışmaktadır. Ağırlıklı ortalama birim katkı payı kaç TL\'dir?', '38 TL', ['40 TL ağırlıklı katkı payı', '42 TL ağırlıklı katkı payı', '34 TL ağırlıklı katkı payı'], 'Ağırlıklı ortalama birim katkı payı = (30 × 0,60) + (50 × 0,40) = 18 + 20 = 38 TL olarak hesaplanır.'),
  ('Bir üretim işletmesi makine başına kısıtlı saat kapasitesine sahipken kârı maksimize etmek için hangi ürüne üretim önceliği vermelidir?', 'Kısıtlı makine saati başına en yüksek katkı paylı ürüne', ['Birim satış fiyatı en yüksek görünen ürüne', 'Birim değişken maliyeti en düşük olan ürüne', 'Toplam sabit maliyeti en az olan ürüne'], 'Darboğaz (kısıt) teorisine göre en yüksek kâr, kıt kaynağın (makine saati) bir birimi başına en fazla katkı payı üreten ürüne öncelik verilerek sağlanır.'),
  ('Dönem net kârı 600.000 TL, tedavüldeki hisse senedi sayısı 200.000 adet ve hisse piyasa fiyatı 24 TL olan bir şirketin Fiyat/Kazanç (F/K) oranı kaçtır?', '8', ['6 fiyat kazanç oranı', '12 fiyat kazanç oranı', '4 fiyat kazanç oranı'], 'Hisse başına kâr = 600.000 / 200.000 = 3 TL; F/K oranı = 24 / 3 = 8 olarak hesaplanır.'),
  ('Bir şirketin Piyasa Değeri / Defter Değeri (PD/DD) oranının 1,00\'in altında olması yatırımcılara ilk bakışta neyi ifade eder?', 'Hissenin özkaynak defter değerinin altında işlem gördüğünü', ['Şirketin özkaynaklarının tamamen negatif olduğunu', 'Hisse fiyatının yıllık kârın yüz katına çıktığını', 'Şirketin hiç borçlanmadan faaliyet yürüttüğünü'], 'PD/DD < 1, borsadaki toplam piyasa değerinin bilançodaki kayıtlı özkaynak toplamından daha düşük fiyatlandığını gösterir.'),
  ('İşletme ortaklarının şirkete 100.000 TL ek nakit sermaye koyması bilanço ve nakit akış tablosunu nasıl etkiler?', 'Varlık ve özkaynak artar, finansman nakit girişi doğar', ['Varlık ve borç artar, işletme nakit girişi doğar', 'Özkaynak değişmez, yatırım nakit girişi doğar', 'Varlık azalır, finansman nakit çıkışı doğar'], 'Sermaye artırımı nakit varlığını ve özkaynakları 100.000 TL artırır; nakit akış tablosunda ise finansman faaliyetlerinden nakit girişi olarak yer alır.'),
  ('Muhasebe hesap işleyiş kurallarına göre aktif (varlık) hesaplarındaki artışlar ve azalışlar hesabın hangi taraflarına kaydedilir?', 'Artışlar borç, azalışlar alacak tarafına', ['Artışlar alacak, azalışlar borç tarafına', 'Hem artışlar hem azalışlar borç tarafına', 'Hem artışlar hem azalışlar alacak tarafına'], 'Varlık hesapları borç kalanı verir; artışlar sol (borç) tarafa, azalışlar ise sağ (alacak) tarafa yazılır.'),
  ('Muhasebe hesap işleyişine göre gelir hesaplarındaki artışlar ile gider hesaplarındaki artışlar sırasıyla hangi taraflara kaydedilir?', 'Gelir alacağa, gider borca', ['Gelir borca, gider alacağa', 'Her ikisi de hesabın borç tarafına', 'Her ikisi de hesabın alacak tarafına'], 'Gelirler özkaynağı artırdığı için alacak tarafına, giderler özkaynağı azalttığı için borç tarafına kaydedilir.'),
  ('Dönem sonunda gelir ve gider hesaplarının kapatılarak net kâr veya zararın belirlenmesi işleminde kullanılan ana özet hesap hangisidir?', 'Dönem kârı veya zararı hesabı', ['Birikmiş amortisman hesabı', 'Gelecek aylara ait gider hesabı', 'Kısa vadeli ticari borç hesabı'], 'Tüm gelir ve gider hesapları dönem sonunda Dönem Kârı veya Zararı hesabına devredilerek kapatılır ve oluşan bakiye bilançodaki özkaynaklara yansıtılır.'),
  ('Bir şirketin ticari borç devir hızı yılda 9 kez ise 360 günlük yıla göre tedarikçilere ortalama borç ödeme süresi kaç gündür?', '40 gün', ['45 gün ödeme süresi', '30 gün ödeme süresi', '60 gün ödeme süresi'], 'Ortalama borç ödeme süresi = 360 / Ticari Borç Devir Hızı = 360 / 9 = 40 gün olarak hesaplanır.'),
  ('Bir işletmenin duran varlık devir hızının sektör ortalamasının çok altında kalması genellikle neyi gösterir?', 'Kapasite kullanımının düşük veya aşırı yatırım yapıldığını', ['Stokların depoda çok hızlı tükendiğini', 'Kısa vadeli ticari borçların tamamen sıfırlandığını', 'Net kâr marjının sektörün iki katına çıktığını'], 'Duran varlık devir hızı = Net Satışlar / Net Maddi Duran Varlıklar olup düşük çıkması fabrika ve makinelerden yeterli satış üretilemediğini (atıl kapasite) gösterir.'),
  ('Toplam özkaynakları 500.000 TL, uzun vadeli borçları 300.000 TL ve duran varlıkları 700.000 TL olan bir işletmede devamlı sermaye tutarı ve net işletme sermayesi kaç TL\'dir?', '800.000 TL ve 100.000 TL', ['800.000 TL ve 200.000 TL', '700.000 TL ve 100.000 TL', '500.000 TL ve 200.000 TL'], 'Devamlı sermaye = Özkaynak + Uzun Vadeli Borç = 500.000 + 300.000 = 800.000 TL; Net İşletme Sermayesi = Devamlı Sermaye − Duran Varlıklar = 800.000 − 700.000 = 100.000 TL\'dir.'),
  ('Doğrudan (direkt) yöntem ile dolaylı (endirekt) yöntem arasındaki fark nakit akış tablosunun yalnızca hangi bölümünün sunumunda ortaya çıkar?', 'İşletme faaliyetleri bölümünde', ['Yatırım faaliyetleri bölümünde', 'Finansman faaliyetleri bölümünde', 'Dönem sonu nakit mevcudunda'], 'Yatırım ve finansman faaliyetleri her iki yöntemde de aynı biçimde raporlanır; yalnızca işletme faaliyetlerinden nakit akışı doğrudan tahsilat-ödemeler veya net kârdan düzeltmeler yoluyla farklı sunulur.'),
  ('Bir işletmenin satış hacmi başabaş noktasının üzerine çıktığında elde edilen her ilave satış biriminin faaliyet kârına katkısı ne kadardır?', 'Birim katkı payı kadar', ['Birim satış fiyatı kadar', 'Birim değişken maliyet kadar', 'Ortalama sabit maliyet kadar'], 'Başabaş noktasında tüm sabit maliyetler tamamen karşılandığı için, bu noktadan sonraki her bir ek satış kendi birim katkı payı kadar doğrudan faaliyet kârını artırır.'),
  ('Bir işletme 40.000 TL tutarındaki ticari malı veresiye (kredili) satın aldığında yevmiye kaydı nasıl yapılır?', 'Ticari Mallar borçlu, Satıcılar alacaklı', ['Satıcılar borçlu, Ticari Mallar alacaklı', 'Ticari Mallar borçlu, Kasa hesabı alacaklı', 'Alıcılar borçlu, Satıcılar hesabı alacaklı'], 'Mal girişi varlık artışı olduğu için Ticari Mallar borçlandırılır; veresiye borç doğduğu için Satıcılar hesabı alacaklandırılır.'),
  ('İşletme ortaklarının şirkete nakit olarak 100.000 TL sermaye eklemesi halinde hangi hesaplar çalışır?', 'Kasa borçlu, Sermaye alacaklı', ['Sermaye borçlu, Kasa hesabı alacaklı', 'Bankalar borçlu, Ticari Borçlar alacaklı', 'Kasa borçlu, Dönem Net Kârı alacaklı'], 'Nakit girişi Kasa (varlık) hesabını borçlandırırken, özkaynak artışı Sermaye hesabını alacaklandırır.'),
  ('Mizan tablosunda borç toplamı ile alacak toplamının birbirine eşit çıkması aşağıdakilerden hangisini kesin olarak kanıtlar?', 'Kayıtlarda borç-alacak dengesi kurulduğunu', ['Tüm işlemlerin doğru hesaplara kaydedildiğini', 'Hiçbir belgenin unutulmadan deftere işlendiğini', 'Stok değerlemesinin hatasız yapıldığını'], 'Mizan eşitliği yalnızca borç ve alacak tutarlarının aritmetik dengesini gösterir; yanlış hesap seçimi veya unutulan kayıtlar mizanı bozmaz.'),
  ('Bir muhasebeci elektrik faturası ödemesini yanlışlıkla Kasa yerine Bankalar hesabından çıkış olarak kaydetmiştir. Bu hata mizanda nasıl bir sonuç doğurur?', 'Borç-alacak toplamları eşit kalır', ['Mizan borç toplamı alacak toplamından fazla çıkar', 'Mizan alacak toplamı borç toplamından fazla çıkar', 'Gelir tablosu toplam gideri hatalı hesaplanır'], 'Yanlış aktif hesabı alacaklandırılmış olsa da toplam alacak tutarı değişmediği için mizanın borç-alacak eşitliği bozulmaz.'),
  ('Gelir (hasılat) hesapları ile gider hesaplarının çift taraflı kayıt işleyişi aşağıdakilerden hangisinde doğru verilmiştir?', 'Gelirler alacakla, giderler borçla artar', ['Gelirler borçla, giderler alacakla artar', 'Hem gelirler hem giderler borçla artar', 'Hem gelirler hem giderler alacakla artar'], 'Gelirler özkaynağı artırdığı için alacak tarafına, giderler özkaynağı azalttığı için borç tarafına yazılarak artırılır.'),
  ('Toplam varlıkları 650.000 TL ve özkaynakları 270.000 TL olan bir işletmenin toplam borçları kaç TL\'dir?', '380.000 TL', ['920.000 TL civarındadır', '270.000 TL seviyesindedir', '420.000 TL olarak hesaplanır'], 'Bilanço eşitliğine göre Borçlar = Varlıklar - Özkaynaklar = 650.000 - 270.000 = 380.000 TL olur.'),
  ('Bilanço kalemleri aktif (varlıklar) tarafında genellikle hangi ilkeye göre yukarıdan aşağıya doğru sıralanır?', 'Likidite derecesine göre', ['Satın alınma tarihine göre', 'Piyasa değerinin büyüklüğüne göre', 'Vergi oranının yüksekliğine göre'], 'Türkiye ve uluslararası uygulamalarda aktif kalemler genellikle en likit olandan (kasa/banka) en az likit olana (duran varlıklar) doğru sıralanır.'),
  ('Gelir tablosunda brüt satış kârı hangi iki kalemin farkı alınarak bulunur?', 'Net satışlar ile satılan malın maliyeti', ['Brüt satışlar ile genel yönetim giderleri', 'Faaliyet kârı ile finansman giderleri', 'Net satışlar ile vergi karşılıkları'], 'Brüt satış kârı, net satış hasılatından doğrudan satılan ürün veya hizmetlerin maliyeti (SMM) çıkarılarak hesaplanır.'),
  ('Net satışları 500.000 TL, satılan malın maliyeti 320.000 TL ve faaliyet giderleri 90.000 TL olan işletmenin esas faaliyet kârı kaç TL\'dir?', '90.000 TL', ['180.000 TL olarak bulunur', '230.000 TL düzeyindedir', '410.000 TL olarak hesaplanır'], 'Önce brüt kâr = 500.000 - 320.000 = 180.000 TL; ardından faaliyet kârı = 180.000 - 90.000 = 90.000 TL bulunur.'),
  ('Satıştan iadeler ve satış iskontoları gelir tablosunda hangi tutardan indirilerek net satışlara ulaşılır?', 'Brüt satışlardan', ['Satılan malın maliyetinden', 'Dönem net kârı tutarından', 'Faaliyet giderleri toplamından'], 'Brüt satış hasılatından satış indirimleri (iadeler ve iskontolar) düşüldüğünde net satışlar elde edilir.'),
  ('Bir işletme ocak başında 10 TL\'den 100 adet, ay ortasında 14 TL\'den 100 adet mal almış ve ay sonunda 120 adet satmıştır. FIFO yöntemine göre satılan malın maliyeti kaç TL\'dir?', '1.280 TL', ['1.600 TL olarak hesaplanır', '1.440 TL düzeyindedir', '1.200 TL seviyesindedir'], 'FIFO\'da ilk 100 adet 10 TL\'den (1.000 TL), kalan 20 adet ise 14 TL\'den (280 TL) çıkar; toplam SMM = 1.280 TL olur.'),
  ('Önceki alışları 10 TL\'den 100 adet ve 14 TL\'den 100 adet olan bir işletme 120 adet satış yaparsa, LIFO yöntemine göre dönem sonu stok değeri kaç TL olur?', '800 TL', ['1.120 TL olarak hesaplanır', '960 TL seviyesindedir', '1.000 TL düzeyindedir'], 'LIFO\'da son 100 adet (14 TL) ve ilk partiden 20 adet (10 TL) satılır; depoda ilk partiden 80 adet x 10 TL = 800 TL kalır.'),
  ('10 TL\'den 100 adet ve 14 TL\'den 100 adet mal alan bir işletmede 120 adet ürün satıldığında ağırlıklı ortalama maliyet yöntemine göre SMM kaç TL\'dir?', '1.440 TL', ['1.280 TL olarak bulunur', '1.600 TL seviyesindedir', '1.200 TL düzeyindedir'], 'Toplam maliyet 1.000 + 1.400 = 2.400 TL, toplam adet 200 olduğundan birim ortalama 12 TL\'dir; 120 x 12 = 1.440 TL olur.'),
  ('Fiyatların sürekli yükseldiği (enflasyonist) bir dönemde hangi stok değerleme yöntemi en yüksek brüt satış kârını verir?', 'FIFO yöntemi', ['LIFO (Son Giren İlk Çıkar) yöntemi', 'Ağırlıklı ortalama maliyet yöntemi', 'Hareketli ağırlıklı ortalama yöntemi'], 'Enflasyonda FIFO eski ve düşük maliyetli malları SMM\'ye yazdığı için satılan malın maliyeti düşük, brüt kâr ise en yüksek çıkar.'),
  ('Enflasyonun yüksek olduğu bir ekonomide, yasal olarak izin verildiği varsayıldığında, vergi yükünü en aza indiren stok değerleme yöntemi hangisidir?', 'LIFO yöntemi', ['FIFO (İlk Giren İlk Çıkar) yöntemi', 'Dönem sonu sabit fiyat yöntemi', 'Özel birim maliyet eşleştirme yöntemi'], 'Enflasyonda LIFO en güncel ve yüksek maliyetleri gider (SMM) yazarak vergi öncesi kârı ve dolayısıyla ödenecek gelir vergisini düşürür.'),
  ('Fiziksel olarak çabuk bozulan gıda ürünlerini satan bir markette gerçek fiziki mal akışına en çok uyan stok maliyet yöntemi hangisidir?', 'FIFO yöntemi', ['LIFO (Son Giren İlk Çıkar) yöntemi', 'Sadece dönem sonu piyasa değerlemesi', 'Geriye dönük maliyet indirimi yöntemi'], 'Bozulabilir ürünlerde eski stoklar önce satıldığı için fiziksel akışla en uyumlu maliyet varsayımı İlk Giren İlk Çıkar (FIFO) yöntemidir.'),
  ('Özellikle mücevherat, sanat eseri veya özel üretim yat gibi birbirinden farklı yüksek değerli ürünlerde en uygun stok değerleme yöntemi hangisidir?', 'Gerçek parti (özel) maliyet yöntemi', ['Hareketli ağırlıklı ortalama yöntemi', 'Dönem sonu LIFO değerleme yöntemi', 'Basit aritmetik fiyat ortalaması'], 'Her biri benzersiz ve yüksek bedelli ürünlerin maliyeti tek tek takip edilebildiğinden gerçek parti maliyeti yöntemi tercih edilir.'),
  ('Birikmiş amortisman hesabı bilançoda hangi nitelikle ve nasıl yer alır?', 'Duran varlıkları azaltan düzenleyici hesap', ['Kısa vadeli yabancı kaynaklar altında borç', 'Özkaynaklar altında dağıtılmamış kâr kalemi', 'Dönen varlıklar altında nakit benzeri kalem'], 'Birikmiş amortisman, aktifte (duran varlıklar altında) eksi işaretiyle yer alarak ilgili varlığın net defter değerini gösterir.'),
  ('100.000 TL maliyetli bir ekipmanın iki yıl sonunda birikmiş amortismanı 35.000 TL ise net defter değeri kaç TL\'dir?', '65.000 TL', ['135.000 TL olarak hesaplanır', '35.000 TL seviyesindedir', '70.000 TL düzeyindedir'], 'Net defter değeri = Varlığın Maliyeti - Birikmiş Amortisman = 100.000 - 35.000 = 65.000 TL olur.'),
  ('Azalan bakiyeler (hızlandırılmış) amortisman yöntemi ilk yıllarda doğrusal yönteme kıyasla gelir tablosunu nasıl etkiler?', 'Daha yüksek gider, daha düşük kâr', ['Daha düşük gider, daha yüksek kâr', 'Amortisman gideri her yıl sabit kalır', 'Gelir tablosu üzerinde hiçbir fark oluşmaz'], 'Hızlandırılmış yöntemde ilk yıllarda daha yüksek amortisman gideri yazıldığı için dönem başlarında vergi öncesi kâr ve vergi daha düşük çıkar.'),
  ('Maddi olmayan duran varlıkların (örneğin bir patentin) maliyetinin yasal veya faydalı ömrü boyunca giderleştirilmesi işlemine ne ad verilir?', 'İtfa', ['Yeniden değerleme artışı', 'Sermaye taahhüt ödemesi', 'Şüpheli alacak karşılığı'], 'Maddi olmayan duran varlıkların değerinin dönemlere yayılarak gider yazılması teknik olarak itfa (amortization) olarak adlandırılır.'),
  ('Bir işletme başka bir şirketi, o şirketin tanımlanabilir net varlıklarının gerçeğe uygun değerinden daha yüksek bir bedelle satın aldığında aradaki fark bilançoda nasıl kaydedilir?', 'Şerefiye', ['Dönem zararları hesabı', 'Kısa vadeli ticari borç', 'Stok değerleme fazlası'], 'Satın alma bedelinin net tanımlanabilir varlıkların adil değerini aşan kısmı marka gücü ve müşteri portföyünü yansıtan şerefiye olarak aktifleştirilir.'),
  ('Likidite (asit-test) oranının cari orandan temel farkı aşağıdakilerden hangisidir?', 'Dönen varlıklardan stokların çıkarılması', ['Kısa vadeli borçlara uzun vadeli borç eklenmesi', 'Dönen varlıklara maddi duran varlık eklenmesi', 'Paydaya yalnızca özkaynakların yazılması'], 'Asit-test oranı = (Dönen Varlıklar - Stoklar) / Kısa Vadeli Borçlar formülüyle hesaplanır ve stok satmadan borç ödeme gücünü ölçer.'),
  ('Cari oranı 2,80 olan ancak asit-test oranı 0,70 çıkan bir işletme hakkında hangi yorum en tutarlıdır?', 'Dönen varlıkların büyük bölümü stoklardadır', ['İşletmenin neredeyse hiç stoku bulunmamaktadır', 'Kısa vadeli borçlar tamamen nakit fazlasıyla kaplıdır', 'İşletme tüm alacaklarını anında nakde çevirmiştir'], 'Cari oran ile asit-test oranı arasındaki büyük uçurum, dönen varlıkların ağır biçimde stoklara bağlı olduğunu gösterir.'),
  ('Bir işletmenin dönen varlıklarından kısa vadeli yabancı kaynaklarının çıkarılmasıyla elde edilen tutara ne ad verilir?', 'Net işletme sermayesi', ['Brüt faaliyet kârı tutarı', 'Toplam finansal kaldıraç', 'Özkaynak devir hızı'], 'Net İşletme Sermayesi = Dönen Varlıklar - Kısa Vadeli Borçlar şeklinde hesaplanır ve günlük faaliyetlerin finansman tamponunu gösterir.'),
  ('İşletmenin çok yüksek bir cari orana (örneğin 6,0) sahip olması finansal analizde hangi olumsuzluğa işaret edebilir?', 'Atıl nakit veya aşırı stok birikimine', ['Kısa vadeli iflas riskinin çok yüksek olduğuna', 'Şirketin hiç dönen varlığa sahip olmadığına', 'Uzun vadeli borçların vadesinin geçtiğine'], 'Aşırı yüksek cari oran, nakdin verimli yatırımlarda değerlendirilmediğini ya da stok ve alacakların eritilemediğini gösterebilir.'),
  ('Stokta kalma süresi 45 gün, alacak tahsil süresi 35 gün ve ticari borç ödeme süresi 30 gün olan bir işletmenin nakit dönüşüm süresi kaç gündür?', '50 gün', ['110 gün olarak hesaplanır', '40 gün seviyesindedir', '20 gün düzeyindedir'], 'Nakit dönüşüm süresi = 45 + 35 - 30 = 50 gündür; işletme bu süreyi işletme sermayesiyle finanse etmek zorundadır.'),
  ('Yıllık satılan malın maliyeti 720.000 TL ve ortalama stok tutarı 90.000 TL olan bir şirketin stok devir hızı kaçtır?', '8', ['0,125 olarak hesaplanır', '12 seviyesindedir', '6 düzeyindedir'], 'Stok devir hızı = Satılan Malın Maliyeti / Ortalama Stok = 720.000 / 90.000 = 8 kez/yıl olarak bulunur.'),
  ('Alacak devir hızı 9 olan bir işletmenin (1 yıl = 360 gün alındığında) ortalama alacak tahsil süresi kaç gündür?', '40 gün', ['90 gün olarak hesaplanır', '36 gün seviyesindedir', '45 gün düzeyindedir'], 'Ortalama Alacak Tahsil Süresi = 360 / Alacak Devir Hızı = 360 / 9 = 40 gün olarak hesaplanır.'),
  ('Birim satış fiyatından birim değişken maliyetin çıkarılmasıyla elde edilen ve her bir ürünün sabit maliyetleri karşılamaya katkısını gösteren tutara ne ad verilir?', 'Birim katkı payı', ['Birim net faaliyet kârı', 'Birim amortisman gideri', 'Ortalama toplam maliyet'], 'Birim katkı payı = Birim Satış Fiyatı - Birim Değişken Maliyet olup başabaş analizinin temel paydasıdır.'),
  ('Aylık sabit maliyetleri 120.000 TL, ürünün birim satış fiyatı 50 TL ve birim değişken maliyeti 30 TL olan bir işletmenin başabaş satış miktarı kaç adettir?', '6.000 adet', ['2.400 adet olarak hesaplanır', '4.000 adet seviyesindedir', '3.000 adet düzeyindedir'], 'Birim katkı payı = 50 - 30 = 20 TL; Başabaş Miktarı = Sabit Maliyet / Birim Katkı Payı = 120.000 / 20 = 6.000 adettir.'),
  ('Sabit maliyetleri 180.000 TL, birim satış fiyatı 100 TL ve birim değişken maliyeti 60 TL olan bir işletmenin başabaş satış tutarı (cirosu) kaç TL\'dir?', '450.000 TL', ['300.000 TL olarak hesaplanır', '270.000 TL seviyesindedir', '540.000 TL düzeyindedir'], 'Katkı payı oranı = (100 - 60) / 100 = 0,40; Başabaş Cirosu = 180.000 / 0,40 = 450.000 TL (veya 4.500 adet x 100 TL) bulunur.'),
  ('Net satışları 800.000 TL, brüt kârı 240.000 TL ve dönem net kârı 80.000 TL olan bir şirketin net kâr marjı yüzde kaçtır?', '%10', ['%30 olarak hesaplanır', '%20 seviyesindedir', '%15 düzeyindedir'], 'Net kâr marjı = (Dönem Net Kârı / Net Satışlar) x 100 = (80.000 / 800.000) x 100 = %10 olarak bulunur.'),
  ('Net satışları 1.200.000 TL ve esas faaliyet kârı 180.000 TL olan bir işletmenin faaliyet kâr marjı yüzde kaçtır?', '%15', ['%12 olarak hesaplanır', '%20 seviyesindedir', '%25 düzeyindedir'], 'Faaliyet kâr marjı = (Esas Faaliyet Kârı / Net Satışlar) x 100 = (180.000 / 1.200.000) x 100 = %15\'tir.'),
  ('Brüt kâr marjı %40 olan bir şirketin faaliyet kâr marjı yalnızca %8 ise bu durum öncelikle neye işaret eder?', 'Faaliyet giderlerinin satışlara göre yüksekliğine', ['Vergi oranlarının aşırı yüksek düzeyde olduğuna', 'Banka kredisi faiz giderlerinin aşırı büyüdüğüne', 'Satılan malın maliyetinin satışları aştığına'], 'Brüt kâr ile faaliyet kârı arasındaki fark pazarlama, genel yönetim ve Ar-Ge gibi faaliyet giderlerinden kaynaklanır.'),
  ('Faaliyet kâr marjı %18 olduğu hâlde net kâr marjı %3\'e düşen bir şirket için en olası neden aşağıdakilerden hangisidir?', 'Yüksek finansman (faiz) ve vergi giderleri', ['Üretimde kullanılan hammadde maliyetlerinin artışı', 'Depodaki ticari malların fiziki olarak azalması', 'Satış personelinin prim giderlerinin yükselmesi'], 'Faaliyet kârı ile net kâr arasında ağırlıklı olarak borçlanma faiz giderleri, kur farkları ve kurumlar vergisi yer alır.'),
  ('Esas faaliyet kârı (FVÖK) 350.000 TL, amortisman ve itfa payları toplamı 70.000 TL olan bir şirketin FAVÖK tutarı kaç TL\'dir?', '420.000 TL', ['280.000 TL olarak hesaplanır', '350.000 TL seviyesindedir', '490.000 TL düzeyindedir'], 'FAVÖK = Faaliyet Kârı (FVÖK) + Amortisman ve İtfa Payları = 350.000 + 70.000 = 420.000 TL olarak bulunur.'),
  ('Analistler farklı ülkelerdeki ve farklı borçlanma yapılarındaki iki şirketin operasyonel gücünü kıyaslarken neden net kâr yerine sıklıkla FAVÖK kullanır?', 'Faiz, vergi ve amortisman farklarını dışladığı için', ['Şirketlerin toplam nakit bakiyesini doğrudan verdiği için', 'Duran varlık yatırım ihtiyacını tamamen kapsadığı için', 'Gelecek yıllardaki vergi oranlarını önceden bildiği için'], 'FAVÖK, farklı borçluluk (faiz), farklı vergi oranları ve farklı amortisman yöntemlerinin etkisini arındırarak saf operasyonel kârlılığı kıyaslar.'),
  ('Dönem net kârı 150.000 TL, toplam varlıkları 1.500.000 TL ve özkaynakları 600.000 TL olan bir işletmenin ROA ve ROE oranları sırasıyla yüzde kaçtır?', '%10 ve %25', ['%25 ve %10 olarak hesaplanır', '%15 ve %20 seviyesindedir', '%10 ve %15 düzeyindedir'], 'ROA = 150.000 / 1.500.000 = %10; ROE = 150.000 / 600.000 = %25 olarak hesaplanır.'),
  ('Özsermaye kârlılığını (ROE) üç temel performans çarpanına ayıran klasik DuPont eşitliği aşağıdakilerden hangisidir?', 'Net Kâr Marjı x Aktif Devir Hızı x Özsermaye Çarpanı', ['Brüt Kâr Marjı x Cari Oran x Stok Devir Hızı', 'FAVÖK Marjı x Asit-Test Oranı x Borç Oranı', 'Net Kâr Marjı x Alacak Devir Hızı x Vergi Oranı'], 'DuPont ayrıştırmasına göre ROE = (Net Kâr / Satışlar) x (Satışlar / Varlıklar) x (Varlıklar / Özkaynaklar) biçimindedir.'),
  ('Net kâr marjı %5, aktif devir hızı 2 ve özsermaye çarpanı (Varlıklar / Özkaynaklar) 2,5 olan bir şirketin DuPont modeline göre ROE değeri yüzde kaçtır?', '%25', ['%10 olarak hesaplanır', '%12,5 seviyesindedir', '%20 düzeyindedir'], 'DuPont eşitliği ile ROE = %5 x 2 x 2,5 = %25 bulunur.'),
  ('Süpermarket zincirleri gibi düşük kâr marjıyla çalışan sektörler DuPont denklemindeki hangi bileşen sayesinde yüksek ROA elde edebilir?', 'Yüksek aktif devir hızı', ['Çok yüksek brüt kâr marjı', 'Çok yüksek finansal kaldıraç', 'Sıfıra yakın stok devir hızı'], 'ROA = Net Kâr Marjı x Aktif Devir Hızı olduğundan, düşük marjlı ancak hızlı satış yapan sektörler varlıklarını hızla döndürerek ROA\'yı yükseltir.'),
  ('Finansal kaldıracın olumlu (pozitif) etki yaratarak özsermaye kârlılığını artırması için temel koşul aşağıdakilerden hangisidir?', 'Varlık getirisinin borçlanma faizinden yüksek olması', ['Borçlanma faizinin varlık getirisinden yüksek olması', 'İşletmenin hiç yabancı kaynak kullanmaması', 'Dönem net kârının sıfır düzeyinde kalması'], 'Borçla finanse edilen yatırımların getirisi (ROA) vergi sonrası borç maliyetini aştığında aradaki fazlalık ortaklara kalır ve ROE yükselir.'),
  ('Esas faaliyet kârının (FVÖK) finansman (faiz) giderlerine bölünmesiyle bulunan ve borç faizlerini ödeme gücünü gösteren oran hangisidir?', 'Faiz karşılama oranı', ['Net işletme sermayesi oranı', 'Özsermaye devir hızı', 'Brüt kâr karşılama oranı'], 'Faiz karşılama oranı (FVÖK / Faiz Giderleri), işletmenin faaliyet kârıyla faiz yükümlülüklerini kaç kat karşılayabildiğini ölçer.'),
  ('Net Finansal Borç / FAVÖK oranı finansal analizde temel olarak neyi ölçer?', 'Borçların kaç yıllık FAVÖK ile ödenebileceğini', ['Stokların yılda kaç defa yenilendiğini', 'Hisse senedinin defter değerine oranını', 'Özkaynakların dönen varlıklara payını'], 'Net Borç / FAVÖK rasyosu, işletmenin mevcut operasyonel kârlılığıyla net borçlarını teorik olarak kaç yılda geri ödeyebileceğini gösterir.'),
  ('Dolaylı yöntemle hazırlanan işletme faaliyetlerinden nakit akışı hesaplanırken dönem net kârına amortisman gideri neden eklenir?', 'Nakit çıkışı doğurmayan bir gider olduğu için', ['Kasaya doğrudan nakit girişi sağladığı için', 'Vergi dairesinden nakit iade alındığı için', 'Stokların satış fiyatını yükselttiği için'], 'Amortisman net kârı azaltmış ancak kasadan para çıkmasına yol açmamıştır; bu yüzden gerçek nakit akışını bulmak için net kâra geri eklenir.'),
  ('Serbest nakit akışı (Free Cash Flow) genel kabul görmüş basit tanımıyla nasıl hesaplanır?', 'İşletme nakit akışı eksi sermaye harcamaları', ['Brüt satış kârı artı amortisman giderleri', 'Dönem net kârı artı uzun vadeli krediler', 'Toplam dönen varlıklar eksi toplam stoklar'], 'Serbest nakit akışı, işletmenin faaliyetlerinden ürettiği nakitten varlık tabanını korumak ve büyütmek için yaptığı sermaye harcamalarının (CapEx) düşülmesiyle bulunur.'),
  ('Bir baz yılın 100 kabul edilerek takip eden yıllardaki finansal kalemlerin o baz yıla göre gelişimini izleyen analiz yöntemine ne ad verilir?', 'Trend (eğilim yüzdeleri) analizi', ['Dikey yapısal yüzde analizi', 'Asit-test likidite analizi', 'Katkı payı başabaş analizi'], 'Trend analizi uzun dönemli gelişim eğilimlerini (örneğin 5 yıllık satış ve maliyet trendini) baz yıl 100 endeksi üzerinden izler.'),
  ('2020 yılında (baz yıl = 100) satışları 400.000 TL olan bir şirketin üç yıl sonra satışları 600.000 TL\'ye ulaşmıştır. Trend analizine göre ilgili yılın endeks değeri kaçtır?', '150', ['67 olarak hesaplanır', '125 seviyesindedir', '200 düzeyindedir'], 'Trend endeksi = (İlgili Yıl Tutarı / Baz Yıl Tutarı) x 100 = (600.000 / 400.000) x 100 = 150 olarak hesaplanır.'),
  ('Trend analizinde bir şirketin satış endeksi 140\'a yükselirken satılan malın maliyeti endeksi 175\'e çıkmışsa hangi sonuç kesinlikle görülür?', 'Brüt kâr marjı daralmıştır', ['Brüt kâr marjı genişlemiştir', 'Stok devir hızı iki katına çıkmıştır', 'Sabit faaliyet giderleri sıfırlanmıştır'], 'Maliyetlerin satışlardan daha hızlı artması, satış başına brüt kâr payının (brüt kâr marjının) düşmesine yol açar.'),
  ('Bir şirketin sabit faaliyet maliyetlerinin toplam maliyet içindeki payının yüksek olması nedeniyle satışlardaki küçük değişimlerin faaliyet kârında büyük dalgalanmalar yaratmasına ne ad verilir?', 'Faaliyet kaldıracı', ['Finansal kaldıraç etkisi', 'Stok değerleme kaldıracı', 'Nakit dönüşüm kaldıracı'], 'Yüksek sabit maliyetli (örneğin havayolu veya yazılım) işletmelerde faaliyet kaldıracı yüksektir; başabaşı geçince kâr hızla artar, düşüşte hızla erir.'),
  ('Bir işletmenin fiili satışları 10.000 adet ve başabaş satış miktarı 7.500 adet ise güvenlik marjı oranı yüzde kaçtır?', '%25', ['%75 olarak hesaplanır', '%33 seviyesindedir', '%20 düzeyindedir'], 'Güvenlik Marjı Oranı = (Fiili Satışlar - Başabaş Satışlar) / Fiili Satışlar = (10.000 - 7.500) / 10.000 = %25\'tir.'),
  ('Güvenlik marjının yüksek olması bir işletme yönetimi açısından neyi ifade eder?', 'Zarara geçmeden önce satış düşüşüne dayanıklılığı', ['Sabit maliyetlerin satış gelirlerini aştığını', 'Kısa vadeli borçların vadesinin dolduğunu', 'Birim değişken maliyetin satış fiyatını geçtiğini'], 'Güvenlik marjı, satışların başabaş noktasına inmeden önce yüzde kaç veya kaç adet düşebileceğini gösteren koruma tamponudur.'),
  ('Net kârı 500.000 TL, toplam hisse adedi 100.000 ve bir hissesinin borsa fiyatı 40 TL olan şirketin Fiyat / Kazanç (F/K) oranı kaçtır?', '8', ['5 olarak hesaplanır', '12,5 seviyesindedir', '4 düzeyindedir'], 'Önce Hisse Başına Kâr (HBK) = 500.000 / 100.000 = 5 TL bulunur; ardından F/K = 40 / 5 = 8 olur.'),
  ('Bir şirketin borsadaki piyasa değerinin bilançosundaki özkaynaklarına (defter değerine) bölünmesiyle elde edilen rasyo hangisidir?', 'PD / DD oranı', ['Fiyat / Kazanç (F/K) oranı', 'Cari likidite oranı', 'Aktif devir hızı oranı'], 'Piyasa Değeri / Defter Değeri (PD/DD), piyasanın şirketin muhasebe özkaynaklarına kaç kat değer biçtiğini gösterir.'),
  ('Bir şirketin dönem başı özkaynakları 400.000 TL, dönem net kârı 120.000 TL ve ortaklara ödediği nakit temettü 30.000 TL ise (sermaye artırımı yoksa) dönem sonu özkaynakları kaç TL olur?', '490.000 TL', ['520.000 TL olarak hesaplanır', '550.000 TL seviyesindedir', '370.000 TL düzeyindedir'], 'Dönem Sonu Özkaynak = Dönem Başı Özkaynak + Net Kâr - Dağıtılan Temettü = 400.000 + 120.000 - 30.000 = 490.000 TL\'dir.'),
  ('Bir işletme ortaklarına nakit temettü (kâr payı) ödediğinde bilanço eşitliği nasıl değişir?', 'Hem varlıklar hem özkaynaklar azalır', ['Varlıklar artarken borçlar aynı tutarda azalır', 'Sadece pasif içinde borçlar artar', 'Gelir tablosunda faaliyet gideri artar'], 'Temettü ödemesi bir gider değil kâr dağıtımıdır; kasadan nakit çıktığı için aktif azalır, dağıtılmamış kâr düştüğü için özkaynak aynı tutarda azalır.'),
  ('Muhasebenin temel kavramlarından ihtiyatlılık (tedbirlilik) kavramı aşağıdakilerden hangisini gerektirir?', 'Olası gider ve zararlar için karşılık ayrılmasını', ['Henüz gerçekleşmemiş satış kârlarının gelir yazılmasını', 'Tüm duran varlıkların amortismanının durdurulmasını', 'Kısa vadeli borçların bilançodan gizlenmesini'], 'İhtiyatlılık ilkesi, muhtemel zarar ve giderler için önceden karşılık ayrılmasını, ancak gerçekleşmemiş gelirlerin kâr olarak kaydedilmemesini öngörür.'),
  ('Tahsil edilmesi kuşkulu hâle gelen ticari alacaklar için şüpheli alacak karşılığı ayrılması hangi temel muhasebe kavramının uygulamasıdır?', 'İhtiyatlılık kavramı', ['Maliyet esası kavramı', 'İşletmenin sürekliliği kavramı', 'Parayla ölçülme kavramı'], 'Alacağın tahsil edilememe olasılığı belirdiğinde zarar kesinleşmeden karşılık gideri yazılması ihtiyatlılık ilkesinin doğrudan gereğidir.'),
  ('Muhasebe politikalarının (örneğin stok değerleme veya amortisman yönteminin) haklı bir neden olmadıkça yıldan yıla değiştirilmemesini isteyen ilke hangisidir?', 'Tutarlılık kavramı', ['Maliyet esası ilkesi', 'Önemlilik kavramı ilkesi', 'Tarafsızlık ve belgelendirme'], 'Tutarlılık kavramı, işletmenin farklı dönemlerdeki finansal tablolarının birbirleriyle sağlıklı biçimde karşılaştırılabilmesini güvence altına alır.'),
  ('İşletmenin peşin ödediği gelecek yıla ait 12 aylık sigorta poliçesi bedeli, ödeme yapıldığı tarihte hangi hesap grubunda izlenir?', 'Dönen varlıklar (Gelecek Aylara Ait Giderler)', ['Gelir tablosu (Genel Yönetim Giderleri)', 'Kısa vadeli yabancı kaynaklar (Ticari Borçlar)', 'Özkaynaklar (Yasal Yedek Akçeler)'], 'Hizmet henüz alınmadığı için peşin ödenen sigorta tutarı gelecekte fayda sağlayacak bir varlıktır; aylar geçtikçe ilgili dönem giderine aktarılır.'),
  ('Net satışları 1.500.000 TL ve ortalama toplam varlıkları 750.000 TL olan bir şirketin aktif devir hızı kaçtır?', '2,0', ['0,50 olarak hesaplanır', '1,50 seviyesindedir', '3,0 düzeyindedir'], 'Aktif Devir Hızı = Net Satışlar / Ortalama Toplam Varlıklar = 1.500.000 / 750.000 = 2,0 olarak hesaplanır.'),
  ('Bir işletmenin maddi duran varlığını, net defter değerinden daha yüksek bir fiyata nakit olarak satması durumunda aradaki fark gelir tablosunu nasıl etkiler?', 'Duran varlık satış kârı (gelir) doğurur', ['Satılan malın maliyeti kalemini artırır', 'Sadece özkaynak sermaye hesabını azaltır', 'Amortisman giderini iki katına çıkarır'], 'Satış bedeli net defter değerini aştığında aradaki pozitif fark diğer olağan/olağandışı gelir (duran varlık satış kârı) olarak kaydedilir.'),
  ('Bir makinenin normal bakım-onarım masrafları ile makinenin üretim kapasitesini artıran büyük revizyon harcaması arasındaki muhasebe farkı nedir?', 'Bakım gider yazılır, kapasite artırımı aktifleştirilir', ['Her ikisi de mutlaka doğrudan dönem gideri yazılır', 'Her ikisi de mutlaka varlık maliyetine eklenir', 'Bakım aktifleştirilir, revizyon doğrudan gider yazılır'], 'Varlığın yalnızca mevcut durumunu koruyan olağan bakımlar giderleşir; faydalı ömrü veya verimliliği artıran harcamalar duran varlık maliyetine eklenir.'),
  ('Kasa ve bankada 120.000 TL\'si, kısa vadeli menkul kıymetlerde 30.000 TL\'si ve kısa vadeli borçlarında 500.000 TL\'si bulunan bir işletmenin nakit oranı kaçtır?', '0,30', ['0,24 olarak hesaplanır', '0,50 seviyesindedir', '0,60 düzeyindedir'], 'Nakit Oranı = (120.000 + 30.000) / 500.000 = 150.000 / 500.000 = 0,30 bulunur.'),
  ('Gelir tablosunda "Brüt Kâr", "Esas Faaliyet Kârı", "Vergi Öncesi Kâr" ve "Dönem Net Kârı" kalemlerinin yukarıdan aşağıya doğru standart sıralaması hangi seçenekte doğrudur?', 'Brüt Kâr → Esas Faaliyet Kârı → Vergi Öncesi Kâr → Dönem Net Kârı', ['Esas Faaliyet Kârı → Brüt Kâr → Dönem Net Kârı → Vergi Öncesi Kâr', 'Brüt Kâr → Vergi Öncesi Kâr → Esas Faaliyet Kârı → Dönem Net Kârı', 'Dönem Net Kârı → Vergi Öncesi Kâr → Esas Faaliyet Kârı → Brüt Kâr'], 'Çok adımlı gelir tablosunda önce SMM düşülerek brüt kâra, sonra faaliyet giderleriyle faaliyet kârına, sonra finansmanla vergi öncesi kâra ve son olarak vergiyle net kâra ulaşılır.'),
  ('Bir işletmenin yasal zorunluluklar veya ana sözleşme gereği dönem kârından ayırıp sermaye yapısını güçlendirmek için bilançoda tuttuğu fonlara ne ad verilir?', 'Yedek akçeler', ['Kısa vadeli mali borçlar', 'Şüpheli alacak karşılıkları', 'Birikmiş amortisman payları'], 'Yedek akçeler, dağıtılmayıp işletme bünyesinde tutulan kâr paylarıdır ve özkaynakları güçlendiren bir finansal tampon görevi görür.'),
  ('Dönem başı stoğu 80.000 TL, dönem içi net mal alışları 320.000 TL ve dönem sonu stoğu 110.000 TL olan bir ticaret işletmesinin satılan malın maliyeti (SMM) kaç TL\'dir?', '290.000 TL', ['400.000 TL olarak hesaplanır', '350.000 TL seviyesindedir', '210.000 TL düzeyindedir'], 'Aralıklı envanter formülüne göre SMM = Dönem Başı Stok + Dönem İçi Net Alışlar - Dönem Sonu Stok = 80.000 + 320.000 - 110.000 = 290.000 TL\'dir.'),
];
